  ('aq-057', 'aptitude', 'quantitative', 'statistics', 2, $q$مجموعة من 5 أشخاص متوسط أعمارهم 12 سنة، ثم انضم إليهم شخص عمره 18 سنة. ما متوسط أعمار أفراد المجموعة الآن بالسنوات؟$q$, null, $q$["12","13","15","15.6"]$q$::jsonb, 75, array[$q$الوسط الحسابي$q$]::text[], (select s.id from public.question_sources s where s.slug = 'jazira-original'), null, null, 'ar', false, true),
  ('aq-058', 'aptitude', 'quantitative', 'statistics', 2, $q$متوسط درجات طالب في 4 اختبارات 80 درجة. ما الدرجة التي يلزمه الحصول عليها في الاختبار الخامس ليصبح متوسط درجاته في الاختبارات الخمسة 82؟$q$, null, $q$["82","84","90","92"]$q$::jsonb, 75, array[$q$الوسط الحسابي$q$]::text[], (select s.id from public.question_sources s where s.slug = 'jazira-original'), null, null, 'ar', false, true),
  ('aq-059', 'aptitude', 'quantitative', 'statistics', 2, $q$إذا أُضيف العدد 5 إلى كل قيمة من قيم مجموعة بيانات، فكيف يتأثر وسطها الحسابي ومداها؟$q$, null, $q$["يزيد الوسط الحسابي بمقدار 5، ويزيد المدى بمقدار 5","يبقى الوسط الحسابي كما هو، ويزيد المدى بمقدار 5","يبقى الوسط الحسابي والمدى كما هما","يزيد الوسط الحسابي بمقدار 5، ويبقى المدى كما هو"]$q$::jsonb, 75, array[$q$الوسط الحسابي$q$, $q$المدى$q$]::text[], (select s.id from public.question_sources s where s.slug = 'jazira-original'), null, null, 'ar', false, true),
  ('aq-060', 'aptitude', 'quantitative', 'statistics', 2, $q$أي مجموعات البيانات الآتية قيمها أكثر تشتتًا حول وسطها الحسابي؟$q$, null, $q$["5، 5، 5، 5","4، 5، 5، 6","10، 11، 12، 13","2، 4، 6، 8"]$q$::jsonb, 75, array[$q$التشتت$q$]::text[], (select s.id from public.question_sources s where s.slug = 'jazira-original'), null, null, 'ar', false, true),
