    ('aq-001', 3, $q$كل حد في المتتابعة يساوي ضعف الحد الذي قبله، فالحد التالي = 16 × 2 = 32.$q$),
    ('aq-002', 1, $q$تُجرى عمليتا القسمة والضرب قبل الجمع: 48 ÷ 4 = 12، و3 × 5 = 15، ثم 12 + 15 = 27.$q$),
    ('aq-003', 0, $q$ثمن الدفاتر 3 × 12 = 36 ريالًا، وثمن القلمين 2 × 5 = 10 ريالات، فالمجموع 46 ريالًا، والباقي 100 − 46 = 54 ريالًا.$q$),
    ('aq-004', 3, $q$7² = 49 و5² = 25، فالناتج 49 − 25 = 24. ويمكن استخدام الفرق بين مربعين: (7 − 5)(7 + 5) = 2 × 12 = 24.$q$),
    ('aq-005', 2, $q$المطلوب هو القاسم المشترك الأكبر للعددين 36 و60: 36 = 2² × 3² و60 = 2² × 3 × 5، فالقاسم المشترك الأكبر = 2² × 3 = 12 طالبًا.$q$),
    ('aq-006', 2, $q$العدد الذي يعطي الباقي 5 عند قسمته على 7 وعلى 6 يزيد بمقدار 5 على مضاعف مشترك للعددين 7 و6، والمضاعف المشترك الأصغر لهما 42، فالأعداد المحققة للشرطين هي 5 و47 و89 وهكذا. وأصغرها المكوّن من رقمين 47، وللتحقق: 47 ÷ 7 = 6 والباقي 5، و47 ÷ 6 = 7 والباقي 5.$q$),
    ('aq-007', 3, $q$يدق الجرسان معًا بعد مرور المضاعف المشترك الأصغر للعددين 15 و25، وهو 75 دقيقة، أي ساعة و15 دقيقة، فيدقان معًا الساعة 9:15 صباحًا.$q$),
    ('aq-008', 2, $q$مضاعفات 3 من 1 إلى 100 عددها 33، ومضاعفات 5 عددها 20، والمضاعفات المشتركة (مضاعفات 15) عددها 6، فالعدد المطلوب = 33 + 20 − 6 = 47.$q$),
    ('aq-009', 3, $q$أرقام آحاد قوى العدد 3 تتكرر كل أربع قوى: 3، 9، 7، 1. وبما أن 22 = 4 × 5 + 2، فرقم الآحاد هو الثاني في الدورة، أي 9.$q$),
    ('aq-010', 1, $q$عدد الأعداد الفردية من 1 إلى 99 هو 50 عددًا، وبتجميعها أزواجًا (1 + 99، 3 + 97، ...) نحصل على 25 زوجًا مجموع كل منها 100، فالمجموع = 25 × 100 = 2500.$q$),
    ('aq-011', 2, $q$25% تساوي الربع، وربع 200 هو 200 ÷ 4 = 50.$q$),
    ('aq-012', 3, $q$نوحّد المقامات على 12: 2/3 = 8/12 و1/4 = 3/12، فالمجموع 8/12 + 3/12 = 11/12.$q$),
    ('aq-013', 0, $q$بتحويل الكسور إلى أعداد عشرية: 2/3 ≈ 0.67، و3/5 = 0.6، و5/8 = 0.625، و7/12 ≈ 0.58، فالكسر الأكبر هو 2/3.$q$),
    ('aq-014', 2, $q$العدد = 45 ÷ 0.15 = 300، وللتحقق: 15% من 300 = 0.15 × 300 = 45.$q$),
    ('aq-015', 1, $q$مقدار الزيادة 100 − 80 = 20 ريالًا، وتُنسب الزيادة إلى السعر الأصلي: 20 ÷ 80 × 100% = 25%.$q$),
    ('aq-016', 3, $q$السعر بعد التخفيض يمثل 80% من السعر الأصلي، فالسعر الأصلي = 640 ÷ 0.8 = 800 ريال.$q$),
    ('aq-017', 1, $q$بعد الزيادة: 200 × 1.1 = 220 ريالًا، وبعد الانخفاض: 220 × 0.9 = 198 ريالًا؛ لأن نسبة الانخفاض حُسبت من سعر أكبر من السعر الأصلي.$q$),
    ('aq-018', 0, $q$العدد = 36 ÷ 3/4 = 36 × 4/3 = 48، ثم 5/6 × 48 = 40.$q$),
    ('aq-019', 0, $q$عدد المشتركين في نادي العلوم = 60% × 40 = 24 طالبًا، وربعهم 24 ÷ 4 = 6 طلاب.$q$),
    ('aq-020', 2, $q$إذا كان العدد الأصلي n فإن n × 1.2 × 0.75 = 1800، أي 0.9n = 1800، ومنه n = 2000 نسمة.$q$),
    ('aq-021', 1, $q$بعد السكن يتبقى 2/3 الراتب، ويُنفق على الطعام 1/4 × 2/3 = 1/6 الراتب، فيبقى 2/3 − 1/6 = 1/2 الراتب، وهو 3000 ريال، إذن الراتب 6000 ريال.$q$),
    ('aq-022', 1, $q$ثمن 3 دفاتر = 3 × 8 = 24 ريالًا، وهو ثمن 4 أقلام، فثمن القلم الواحد = 24 ÷ 4 = 6 ريالات.$q$),
    ('aq-023', 0, $q$لكل 5 كتب أدبية 3 كتب علمية، وبما أن 20 = 5 × 4، فعدد الكتب العلمية = 3 × 4 = 12 كتابًا.$q$),
    ('aq-024', 0, $q$معدل الطباعة 45 ÷ 3 = 15 صفحة في الدقيقة، فالزمن اللازم = 120 ÷ 15 = 8 دقائق.$q$),
    ('aq-025', 3, $q$نسبة الدقيق إلى السكر 3 : 2، فكمية السكر = 7.5 × 2 ÷ 3 = 5 أكواب.$q$),
    ('aq-026', 2, $q$مجموع أجزاء النسبة 4 + 5 = 9، وقيمة الجزء الواحد 360 ÷ 9 = 40 ريالًا، فنصيب فهد = 5 × 40 = 200 ريال.$q$),
    ('aq-027', 1, $q$المسافة الحقيقية = 6 × 50000 = 300000 سم، وبما أن 1 كم = 100000 سم، فالمسافة = 3 كم.$q$),
    ('aq-028', 0, $q$عدد العمال يتناسب عكسيًا مع عدد الأيام؛ فالعمل كله يعادل 6 × 12 = 72 يومًا لعامل واحد، وإذا تقاسمه 8 عمال احتاجوا إلى 72 ÷ 8 = 9 أيام.$q$),
    ('aq-029', 3, $q$نوحّد عدد الكرات الزرقاء في النسبتين: الحمراء : الزرقاء = 8 : 12، والزرقاء : الخضراء = 12 : 15، فتكون الحمراء : الخضراء = 8 : 15.$q$),
    ('aq-030', 0, $q$كمية العصير الطبيعي = 0.3 × 20 + 0.1 × 30 = 6 + 3 = 9 لترات من أصل 50 لترًا، فالنسبة = 9 ÷ 50 × 100% = 18%.$q$),
    ('aq-031', 2, $q$نفرض العددين 3k و7k، فيكون 2(3k + 6) = 7k + 6، أي 6k + 12 = 7k + 6، ومنه k = 6، فالعددان 18 و42، ومجموعهما 60.$q$),
    ('aq-032', 0, $q$بقسمة طرفي المعادلة على 3: x = 21 ÷ 3 = 7.$q$),
    ('aq-033', 3, $q$بالتعويض: (−2)² − 3 × (−2) = 4 + 6 = 10.$q$),
    ('aq-034', 3, $q$بتوزيع الضرب على القوسين: 3x + 12 − 2x = x + 12.$q$),
    ('aq-035', 3, $q$بإضافة 3 إلى الطرفين: 2x > 10، ثم بقسمة الطرفين على 2: x > 5.$q$),
    ('aq-036', 2, $q$x² − y² = (x + y)(x − y) = 10 × 4 = 40. وللتحقق: x = 7 وy = 3، و49 − 9 = 40.$q$),
    ('aq-037', 3, $q$نفرض الأعداد n − 1 وn وn + 1، فمجموعها 3n = 72، ومنه n = 24، فأكبرها 25.$q$),
    ('aq-038', 1, $q$نفرض عمر الابن x فعمر الأب 3x، وبعد 12 سنة: 3x + 12 = 2(x + 12)، أي 3x + 12 = 2x + 24، ومنه x = 12 سنة.$q$),
    ('aq-039', 0, $q$نبدأ بما داخل القوسين: 2 ⊕ 3 = 2 × 3 − (2 + 3) = 1، ثم 4 ⊕ 1 = 4 × 1 − (4 + 1) = −1.$q$),
    ('aq-040', 2, $q$من x² = 9 نجد x = 3 أو x = −3، وبما أن x < 0 فإن x = −3، ومنه x² + 2x = 9 − 6 = 3.$q$),
    ('aq-041', 1, $q$بتربيع طرفي المعادلة: x² + 2 + 1/x² = 25، ومنه x² + 1/x² = 25 − 2 = 23.$q$),
    ('aq-042', 0, $q$نفرض ثمن القلم x ريالًا وثمن الدفتر y ريالًا، فيكون 3x + 2y = 27 و2x + 3y = 33. بجمع المعادلتين: 5x + 5y = 60، أي x + y = 12، وبطرح الأولى من الثانية: y − x = 6، فثمن القلم x = (12 − 6) ÷ 2 = 3 ريالات.$q$),
    ('aq-043', 1, $q$مجموع قياسات زوايا المثلث الداخلية 180°، فقياس الزاوية الثالثة = 180° − (65° + 45°) = 70°.$q$),
    ('aq-044', 0, $q$القطر وتر في مثلث قائم ضلعا القائمة فيه 12 و5، فطوله = √(12² + 5²) = √169 = 13 سم.$q$),
    ('aq-045', 0, $q$محيط الدائرة = 2πr ≈ 2 × 22/7 × 7 = 44 سم.$q$),
    ('aq-046', 2, $q$طول ضلع المربع = 36 ÷ 4 = 9 سم، فمساحته = 9² = 81 سم².$q$),
    ('aq-047', 1, $q$الزاويتان الداخليتان الواقعتان في جهة واحدة من القاطع متكاملتان (مجموعهما 180°)، فقياس الأخرى = 180° − 115° = 65°.$q$),
    ('aq-048', 0, $q$مجموع قياسات الزوايا الخارجية لأي مضلع 360°، والزوايا الخارجية للمضلع المنتظم متطابقة، فعدد أضلاعه = 360° ÷ 36° = 10، ومجموع قياسات زواياه الداخلية = (10 − 2) × 180° = 1440°. وللتحقق: قياس كل زاوية داخلية = 180° − 36° = 144°، و10 × 144° = 1440°.$q$),
    ('aq-049', 2, $q$حجم الأسطوانة = مساحة القاعدة × الارتفاع = π × 3² × 10 = 90π سم³.$q$),
    ('aq-050', 3, $q$إذا كان طول الضلع 10 أصبح 12، فتزداد المساحة من 100 إلى 144، أي بمقدار 44 من 100، وهذا يساوي 44%.$q$),
    ('aq-051', 0, $q$المسافة = √((4 − 1)² + (6 − 2)²) = √(9 + 16) = √25 = 5.$q$),
    ('aq-052', 1, $q$قطر الدائرة = 10π ÷ π = 10 سم، وهو نفسه قطر المربع، ومساحة المربع = (طول القطر)² ÷ 2 = 100 ÷ 2 = 50 سم².$q$),
    ('aq-053', 0, $q$طول الوتر = √(6² + 8²) = 10 سم، ومساحة المثلث = (6 × 8) ÷ 2 = 24 سم²، وهي تساوي (10 × الارتفاع) ÷ 2، فالارتفاع = 48 ÷ 10 = 4.8 سم.$q$),
    ('aq-054', 1, $q$الوسط الحسابي = مجموع القيم ÷ عددها = (4 + 8 + 12) ÷ 3 = 24 ÷ 3 = 8.$q$),
    ('aq-055', 2, $q$المدى = أكبر قيمة − أصغر قيمة = 23 − 6 = 17.$q$),
    ('aq-056', 2, $q$نرتب القيم تصاعديًا: 7، 9، 10، 12، 15، 20. عدد القيم زوجي، فالوسيط هو متوسط القيمتين الوسطيين: (10 + 12) ÷ 2 = 11.$q$),
    ('aq-057', 1, $q$مجموع الأعمار = 5 × 12 = 60 سنة، وبعد الانضمام يصبح 60 + 18 = 78 سنة لستة أشخاص، فالمتوسط = 78 ÷ 6 = 13 سنة.$q$),
    ('aq-058', 2, $q$المجموع المطلوب = 5 × 82 = 410، ومجموع درجات الاختبارات الأربعة = 4 × 80 = 320، فالدرجة اللازمة = 410 − 320 = 90.$q$),
    ('aq-059', 3, $q$إضافة 5 إلى كل قيمة تزيد المجموع بمقدار 5 × عدد القيم، فيزيد الوسط الحسابي بمقدار 5. أما المدى فهو الفرق بين أكبر قيمة وأصغر قيمة، وكلتاهما تزيد بمقدار 5، فيبقى الفرق كما هو.$q$),
    ('aq-060', 3, $q$نقيس بُعد القيم عن وسطها الحسابي في كل مجموعة: المجموعة 5، 5، 5، 5 وسطها 5 ولا تبعد عنه أي قيمة، والمجموعة 4، 5، 5، 6 وسطها 5 وأبعد قيمها عنه بمقدار 1، والمجموعة 10، 11، 12، 13 وسطها 11.5 وأبعد قيمها عنه بمقدار 1.5، أما المجموعة 2، 4، 6، 8 فوسطها 5 وتبعد قيمها عنه بمقادير 3، 1، 1، 3. فالمجموعة 2، 4، 6، 8 هي الأكثر تشتتًا، ويؤكد ذلك المدى أيضًا: 0 و2 و3 و6 على الترتيب.$q$),
    ('aq-061', 0, $q$مجموع الأعداد = 5 × 10 = 50، والعدد الأوسط بعد الترتيب 12. ولأن الأعداد صحيحة موجبة مختلفة، فأصغر عددين ممكنين قبل الوسيط هما 1 و2، وأصغر عدد ممكن بعده هو 13. إذن أكبر عدد = 50 − (1 + 2 + 12 + 13) = 22، وهو أكبر من 13 فالترتيب صحيح: 1، 2، 12، 13، 22.$q$),
    ('aq-062', 3, $q$أعلى مبيعات يومية 65 كتابًا (الأربعاء)، وأدناها 30 كتابًا (الثلاثاء)، فالفرق = 65 − 30 = 35 كتابًا.$q$),
    ('aq-063', 2, $q$التغير عن اليوم السابق: الأحد ارتفعت 3 درجات، والاثنين انخفضت 5 درجات، والثلاثاء ارتفعت 7 درجات، والأربعاء ارتفعت درجتين، فأكبر ارتفاع كان يوم الثلاثاء، مع أن أعلى درجة حرارة سُجلت يوم الأربعاء.$q$),
    ('aq-064', 2, $q$نسبة الادخار = 100% − (30% + 25% + 15% + 10%) = 20%، فالمبلغ المدخر = 20% × 12000 = 2400 ريال.$q$),
    ('aq-065', 3, $q$نسبة الزيادة في الشهر الثاني = (1600 − 1280) ÷ 1280 = 25%، وفي الشهر الثالث = (2000 − 1600) ÷ 1600 = 25%، فالعدد المتوقع في الشهر الرابع = 2000 × 1.25 = 2500 زائر. ولا يصح إضافة الفرق الأخير (400) مرة أخرى؛ لأن الزيادة ثابتة في نسبتها لا في مقدارها.$q$),
    ('aq-066', 1, $q$نسبة نشاط الرسم = 60° ÷ 360° = 1/6، فعدد الطلاب الذين اختاروه = 540 ÷ 6 = 90 طالبًا.$q$),
    ('aq-067', 2, $q$سعر الجيجابايت في الباقة (أ) = 90 ÷ 30 = 3 ريالات، وفي الباقة (ب) = 120 ÷ 50 = 2.4 ريال، فالفرق = 3 − 2.4 = 0.6 ريال.$q$),
    ('aq-068', 1, $q$نسبة السلعة (أ) من الإنتاج الكلي: 2020: 30 ÷ 75 = 40%، و2021: 40 ÷ 80 = 50%، و2022: 45 ÷ 100 = 45%، و2023: 60 ÷ 150 = 40%، فالنسبة الأكبر كانت عام 2021، مع أن أكبر إنتاج للسلعة (أ) كان عام 2023.$q$),
    ('aq-069', 1, $q$عدد الحاضرين = 90% × 20 + 70% × 50 + 80% × 30 = 18 + 35 + 24 = 77 طالبًا من أصل 100، فالنسبة 77%. ولا يصح أخذ متوسط النسب الثلاث (80%) لاختلاف أعداد المسجلين.$q$),
    ('aq-070', 0, $q$3/4 = 0.75، و0.75 > 0.7، فالقيمة الأولى أكبر.$q$),
    ('aq-071', 2, $q$20% من 150 = 0.2 × 150 = 30، و30% من 100 = 30، فالقيمتان متساويتان.$q$),
    ('aq-072', 1, $q$القيمة الأولى = √100 = 10، والقيمة الثانية = 8 + 6 = 14، فالقيمة الثانية أكبر؛ لأن الجذر التربيعي لمجموع عددين موجبين أصغر من مجموع جذريهما: √(a + b) < √a + √b.$q$),
    ('aq-073', 1, $q$0.2 × 0.3 = 0.06، و0.06 < 0.6، فالقيمة الثانية أكبر.$q$),
    ('aq-074', 2, $q$محيط المثلث = 3 × 6 = 18 سم، ومحيط المربع = 4 × 4.5 = 18 سم، فالقيمتان متساويتان.$q$),
    ('aq-075', 0, $q$الأعداد الأولية بين 10 و20 هي 11، 13، 17، 19 (أربعة أعداد)، وبين 20 و30 هي 23، 29 (عددان)، فالقيمة الأولى أكبر.$q$),
    ('aq-076', 0, $q$مساحة الدائرة = π × 3² = 9π ≈ 28.3 سم²، ومساحة المربع = 5² = 25 سم²، فالقيمة الأولى أكبر.$q$),
    ('aq-077', 1, $q$متوسط السرعة = المسافة ÷ الزمن = 120 ÷ 2.5 = 48 كم/ساعة، و48 < 50، فالقيمة الثانية أكبر.$q$),
    ('aq-078', 3, $q$إذا كان x = 2 فإن x² = 4 وهي أكبر من x، وإذا كان x = 1/2 فإن x² = 1/4 وهي أصغر من x، وإذا كان x = 1 تساوت القيمتان، فالعلاقة غير ثابتة والمعطيات غير كافية للمقارنة.$q$),
    ('aq-079', 3, $q$إذا كان a = b = 5 فإن a × b = 25 فتتساوى القيمتان، وإذا كان a = 2 وb = 8 فإن a × b = 16 فتكون القيمة الثانية أكبر، فالعلاقة غير ثابتة والمعطيات غير كافية للمقارنة.$q$),
    ('aq-080', 3, $q$نفرض العمرين 3k و4k، فالقيمة الأولى 3k + 5 والثانية 4k. إذا كان عمرا سالم وماجد 15 و20 تساوت القيمتان (20 و20)، وإذا كانا 6 و8 كانت الأولى أكبر (11 مقابل 8)، فالمعطيات غير كافية للمقارنة.$q$)
  ) as v (key, correct_index, explanation)
  join public.questions q on q.key = v.key
on conflict (question_id) do update set
  correct_index = excluded.correct_index,
  explanation   = excluded.explanation
where (k.correct_index, k.explanation) is distinct from (excluded.correct_index, excluded.explanation);

