  ('av-043', 'aptitude', 'verbal', 'odd-word-out', 2, $q$اختر الكلمة المختلفة عن بقية الكلمات:$q$, null, $q$["سيف","درع","رمح","خنجر"]$q$::jsonb, 35, array[$q$مفردة شاذة$q$, $q$أسلحة$q$]::text[], (select s.id from public.question_sources s where s.slug = 'jazira-original'), null, null, 'ar', false, true),
  ('av-044', 'aptitude', 'verbal', 'odd-word-out', 2, $q$اختر الكلمة المختلفة عن بقية الكلمات:$q$, null, $q$["يتأمّل","يتذكّر","يتدبّر","يتفكّر"]$q$::jsonb, 40, array[$q$مفردة شاذة$q$, $q$ترادف$q$]::text[], (select s.id from public.question_sources s where s.slug = 'jazira-original'), null, null, 'ar', false, true),
  ('av-045', 'aptitude', 'verbal', 'odd-word-out', 3, $q$اختر الكلمة المختلفة عن بقية الكلمات:$q$, null, $q$["سُهاد","أرَق","سَهَر","رُقاد"]$q$::jsonb, 45, array[$q$مفردة شاذة$q$, $q$مفردات$q$]::text[], (select s.id from public.question_sources s where s.slug = 'jazira-original'), null, null, 'ar', false, true),
  ('av-046', 'aptitude', 'verbal', 'reading-comprehension', 1, $q$ما الفكرة الرئيسة للنص؟$q$, $q$ارتبطت النخلة بحياة سكان الجزيرة العربية منذ القدم ارتباطًا وثيقًا؛ فقد كانت ثمارها غذاءً رئيسًا يسهل حفظه في مواسم الشحّ، وكانت أجزاؤها موردًا لا يُهدَر منه شيء: فمن سعفها صُنعت السلال والحُصُر، ومن جذوعها سُقِفت البيوت، ومن أليافها فُتِلت الحبال. ولم تكن هذه المنافع وحدها سرّ مكانتها، بل إن قدرتها على تحمّل الحرارة وملوحة التربة جعلتها رفيقة الإنسان في بيئة قاسية قلّما يصمد فيها غيرها. وفي العصر الحديث لم تتراجع أهميتها، إذ تحوّلت زراعتها إلى صناعة تقوم على أساليب ريّ حديثة تقتصد في استهلاك الماء، وعلى مصانع تُعبّئ التمور وتُصدّرها إلى أسواق بعيدة، فصار ما كان قوتًا محليًا سلعةً يعرفها العالم.$q$, $q$["مكانة النخلة في حياة الإنسان قديمًا وحديثًا","طرق صناعة الحبال والسلال من النخيل","أساليب الريّ الحديثة التي تقتصد في استهلاك الماء","أسواق تصدير التمور في العالم المعاصر"]$q$::jsonb, 60, array[$q$استيعاب المقروء$q$, $q$الفكرة الرئيسة$q$]::text[], (select s.id from public.question_sources s where s.slug = 'jazira-original'), null, null, 'ar', false, true),
  ('av-047', 'aptitude', 'verbal', 'reading-comprehension', 2, $q$بحسب النص، ما الذي جعل النخلة «رفيقة الإنسان» في بيئته القاسية؟$q$, $q$ارتبطت النخلة بحياة سكان الجزيرة العربية منذ القدم ارتباطًا وثيقًا؛ فقد كانت ثمارها غذاءً رئيسًا يسهل حفظه في مواسم الشحّ، وكانت أجزاؤها موردًا لا يُهدَر منه شيء: فمن سعفها صُنعت السلال والحُصُر، ومن جذوعها سُقِفت البيوت، ومن أليافها فُتِلت الحبال. ولم تكن هذه المنافع وحدها سرّ مكانتها، بل إن قدرتها على تحمّل الحرارة وملوحة التربة جعلتها رفيقة الإنسان في بيئة قاسية قلّما يصمد فيها غيرها. وفي العصر الحديث لم تتراجع أهميتها، إذ تحوّلت زراعتها إلى صناعة تقوم على أساليب ريّ حديثة تقتصد في استهلاك الماء، وعلى مصانع تُعبّئ التمور وتُصدّرها إلى أسواق بعيدة، فصار ما كان قوتًا محليًا سلعةً يعرفها العالم.$q$, $q$["سهولة تصدير ثمارها إلى أسواق بعيدة","قدرتها على تحمّل الحرارة وملوحة التربة","حاجتها إلى كميات كبيرة من الماء","استعمال جذوعها في تسقيف البيوت وأليافها في فتل الحبال"]$q$::jsonb, 60, array[$q$استيعاب المقروء$q$, $q$تفاصيل$q$]::text[], (select s.id from public.question_sources s where s.slug = 'jazira-original'), null, null, 'ar', false, true),
  ('av-048', 'aptitude', 'verbal', 'reading-comprehension', 2, $q$يُفهم من عبارة «صار ما كان قوتًا محليًا سلعةً يعرفها العالم» أن التمور:$q$, $q$ارتبطت النخلة بحياة سكان الجزيرة العربية منذ القدم ارتباطًا وثيقًا؛ فقد كانت ثمارها غذاءً رئيسًا يسهل حفظه في مواسم الشحّ، وكانت أجزاؤها موردًا لا يُهدَر منه شيء: فمن سعفها صُنعت السلال والحُصُر، ومن جذوعها سُقِفت البيوت، ومن أليافها فُتِلت الحبال. ولم تكن هذه المنافع وحدها سرّ مكانتها، بل إن قدرتها على تحمّل الحرارة وملوحة التربة جعلتها رفيقة الإنسان في بيئة قاسية قلّما يصمد فيها غيرها. وفي العصر الحديث لم تتراجع أهميتها، إذ تحوّلت زراعتها إلى صناعة تقوم على أساليب ريّ حديثة تقتصد في استهلاك الماء، وعلى مصانع تُعبّئ التمور وتُصدّرها إلى أسواق بعيدة، فصار ما كان قوتًا محليًا سلعةً يعرفها العالم.$q$, $q$["تجاوزت الاستهلاك المحلي إلى التجارة العالمية","فقدت قيمتها الغذائية بعد تصنيعها وتعبئتها في المصانع","أصبحت تُزرع في بلدان كثيرة خارج الجزيرة","لم تعد غذاءً يعتمد عليه سكان الجزيرة العربية"]$q$::jsonb, 60, array[$q$استيعاب المقروء$q$, $q$استنتاج$q$]::text[], (select s.id from public.question_sources s where s.slug = 'jazira-original'), null, null, 'ar', false, true),
  ('av-049', 'aptitude', 'verbal', 'reading-comprehension', 1, $q$بحسب النص، ماذا يفعل الدماغ في أثناء النوم؟$q$, $q$يظنّ كثير من الطلاب أن السهر في مراجعة الدروس ليلة الاختبار يضمن لهم تحصيلًا أعلى، غير أن الدراسات في علم النفس المعرفي تشير إلى خلاف ذلك. فالدماغ لا يتوقف عن العمل في أثناء النوم، بل يُعيد ترتيب ما اكتسبه خلال اليوم، فيُثبّت المهمّ منه في الذاكرة طويلة المدى. ولذلك فإن من يحرم نفسه النوم قد يحفظ كمًّا كبيرًا من المعلومات في ساعات متأخرة، لكنه قد يجد صعوبة في استرجاعها حين يحتاج إليها. ويرى المختصون أن توزيع المراجعة على أيام متعددة، مع نوم كافٍ ومنتظم، أجدى من حشو المعلومات في ليلة واحدة؛ فالتعلّم الراسخ يحتاج إلى وقت كي يستقرّ.$q$, $q$["يتوقف عن العمل كليًا ليستعيد نشاطه في الصباح","يُثبّت المعلومات المهمة في الذاكرة طويلة المدى","يمحو ما اكتسبه من معلومات خلال اليوم","يُثبّت كل ما اكتسبه خلال اليوم دون تمييز"]$q$::jsonb, 60, array[$q$استيعاب المقروء$q$, $q$تفاصيل$q$]::text[], (select s.id from public.question_sources s where s.slug = 'jazira-original'), null, null, 'ar', false, true),
  ('av-050', 'aptitude', 'verbal', 'reading-comprehension', 2, $q$ما المقصود بعبارة «حشو المعلومات في ليلة واحدة» في النص؟$q$, $q$يظنّ كثير من الطلاب أن السهر في مراجعة الدروس ليلة الاختبار يضمن لهم تحصيلًا أعلى، غير أن الدراسات في علم النفس المعرفي تشير إلى خلاف ذلك. فالدماغ لا يتوقف عن العمل في أثناء النوم، بل يُعيد ترتيب ما اكتسبه خلال اليوم، فيُثبّت المهمّ منه في الذاكرة طويلة المدى. ولذلك فإن من يحرم نفسه النوم قد يحفظ كمًّا كبيرًا من المعلومات في ساعات متأخرة، لكنه قد يجد صعوبة في استرجاعها حين يحتاج إليها. ويرى المختصون أن توزيع المراجعة على أيام متعددة، مع نوم كافٍ ومنتظم، أجدى من حشو المعلومات في ليلة واحدة؛ فالتعلّم الراسخ يحتاج إلى وقت كي يستقرّ.$q$, $q$["تلخيص المعلومات كلها في ورقة واحدة","تكديس معلومات كثيرة في وقت قصير","توزيع المراجعة على أيام متعددة","مراجعة المعلومات مع نوم كافٍ ومنتظم"]$q$::jsonb, 60, array[$q$استيعاب المقروء$q$, $q$معنى عبارة$q$]::text[], (select s.id from public.question_sources s where s.slug = 'jazira-original'), null, null, 'ar', false, true),
  ('av-051', 'aptitude', 'verbal', 'reading-comprehension', 3, $q$أيّ العبارات الآتية يؤيّدها النص؟$q$, $q$يظنّ كثير من الطلاب أن السهر في مراجعة الدروس ليلة الاختبار يضمن لهم تحصيلًا أعلى، غير أن الدراسات في علم النفس المعرفي تشير إلى خلاف ذلك. فالدماغ لا يتوقف عن العمل في أثناء النوم، بل يُعيد ترتيب ما اكتسبه خلال اليوم، فيُثبّت المهمّ منه في الذاكرة طويلة المدى. ولذلك فإن من يحرم نفسه النوم قد يحفظ كمًّا كبيرًا من المعلومات في ساعات متأخرة، لكنه قد يجد صعوبة في استرجاعها حين يحتاج إليها. ويرى المختصون أن توزيع المراجعة على أيام متعددة، مع نوم كافٍ ومنتظم، أجدى من حشو المعلومات في ليلة واحدة؛ فالتعلّم الراسخ يحتاج إلى وقت كي يستقرّ.$q$, $q$["السهر يمنع الطالب من حفظ أي معلومة جديدة","النوم الطويل وحده كافٍ لضمان التفوق في الاختبار","السهر يُضعف الحفظ أكثر ممّا يُضعف الاسترجاع","كثرة ما يُحفظ ليلة الاختبار لا تضمن سهولة استرجاعه"]$q$::jsonb, 60, array[$q$استيعاب المقروء$q$, $q$استنتاج$q$]::text[], (select s.id from public.question_sources s where s.slug = 'jazira-original'), null, null, 'ar', false, true),
  ('av-052', 'aptitude', 'verbal', 'reading-comprehension', 1, $q$بحسب النص، ما الذي يجعل المناطق الصحراوية مناسبة لتوليد الكهرباء من الطاقة الشمسية؟$q$, $q$تتمتّع المناطق الصحراوية بساعات سطوع شمسي طويلة على مدار العام، وهو ما يجعلها من أنسب البيئات لتوليد الكهرباء من الطاقة الشمسية. وتعتمد الألواح الشمسية على خلايا تحوّل ضوء الشمس مباشرةً إلى تيار كهربائي، دون أن تُطلق غازات ملوِّثة في أثناء تشغيلها. غير أن هذه التقنية تواجه تحدّيات في البيئة الصحراوية نفسها؛ فالغبار المتراكم على الألواح يحجب جزءًا من الضوء فيُضعف إنتاجها، كما أن الارتفاع الشديد في درجات الحرارة يقلّل كفاءة الخلايا. ولهذا يعمل المهندسون على تطوير أنظمة تنظيف تستهلك قليلًا من الماء أو لا تستهلكه، وعلى تصميم ألواح أقدر على تحمّل الحرارة، حتى تتحوّل وفرة الشمس إلى وفرة في الطاقة فعلًا.$q$, $q$["اعتدال درجات الحرارة في معظم الأوقات","قلّة الغبار المتراكم في أجوائها","طول ساعات السطوع الشمسي على مدار العام","توافر كميات كبيرة من الماء لتنظيف الألواح"]$q$::jsonb, 60, array[$q$استيعاب المقروء$q$, $q$تفاصيل$q$]::text[], (select s.id from public.question_sources s where s.slug = 'jazira-original'), null, null, 'ar', false, true),
  ('av-053', 'aptitude', 'verbal', 'reading-comprehension', 2, $q$ما وظيفة عبارة «غير أن هذه التقنية تواجه تحدّيات في البيئة الصحراوية نفسها» في بناء النص؟$q$, $q$تتمتّع المناطق الصحراوية بساعات سطوع شمسي طويلة على مدار العام، وهو ما يجعلها من أنسب البيئات لتوليد الكهرباء من الطاقة الشمسية. وتعتمد الألواح الشمسية على خلايا تحوّل ضوء الشمس مباشرةً إلى تيار كهربائي، دون أن تُطلق غازات ملوِّثة في أثناء تشغيلها. غير أن هذه التقنية تواجه تحدّيات في البيئة الصحراوية نفسها؛ فالغبار المتراكم على الألواح يحجب جزءًا من الضوء فيُضعف إنتاجها، كما أن الارتفاع الشديد في درجات الحرارة يقلّل كفاءة الخلايا. ولهذا يعمل المهندسون على تطوير أنظمة تنظيف تستهلك قليلًا من الماء أو لا تستهلكه، وعلى تصميم ألواح أقدر على تحمّل الحرارة، حتى تتحوّل وفرة الشمس إلى وفرة في الطاقة فعلًا.$q$, $q$["تأكيد مزايا الطاقة الشمسية المذكورة قبلها","الانتقال من عرض المزايا إلى الصعوبات","تقديم حلّ عملي لمشكلة الغبار على الألواح","تلخيص الفكرة الرئيسة للنص كله"]$q$::jsonb, 60, array[$q$استيعاب المقروء$q$, $q$بناء النص$q$]::text[], (select s.id from public.question_sources s where s.slug = 'jazira-original'), null, null, 'ar', false, true),
  ('av-054', 'aptitude', 'verbal', 'reading-comprehension', 3, $q$يُفهم من قول الكاتب «حتى تتحوّل وفرة الشمس إلى وفرة في الطاقة فعلًا» أنّ:$q$, $q$تتمتّع المناطق الصحراوية بساعات سطوع شمسي طويلة على مدار العام، وهو ما يجعلها من أنسب البيئات لتوليد الكهرباء من الطاقة الشمسية. وتعتمد الألواح الشمسية على خلايا تحوّل ضوء الشمس مباشرةً إلى تيار كهربائي، دون أن تُطلق غازات ملوِّثة في أثناء تشغيلها. غير أن هذه التقنية تواجه تحدّيات في البيئة الصحراوية نفسها؛ فالغبار المتراكم على الألواح يحجب جزءًا من الضوء فيُضعف إنتاجها، كما أن الارتفاع الشديد في درجات الحرارة يقلّل كفاءة الخلايا. ولهذا يعمل المهندسون على تطوير أنظمة تنظيف تستهلك قليلًا من الماء أو لا تستهلكه، وعلى تصميم ألواح أقدر على تحمّل الحرارة، حتى تتحوّل وفرة الشمس إلى وفرة في الطاقة فعلًا.$q$, $q$["الطاقة الشمسية أرخص مصادر الطاقة المتاحة في الصحراء","الألواح الحالية لا تُنتج أي كهرباء في الصحراء","وفرة الشمس وحدها لا تضمن إنتاجًا وفيرًا من الطاقة","المهندسين نجحوا في التغلّب على جميع التحديات"]$q$::jsonb, 60, array[$q$استيعاب المقروء$q$, $q$استنتاج$q$]::text[], (select s.id from public.question_sources s where s.slug = 'jazira-original'), null, null, 'ar', false, true),
  ('av-055', 'aptitude', 'verbal', 'reading-comprehension', 1, $q$بحسب النص، متى يكون التنقّل السريع بين الفقرات مقبولًا؟$q$, $q$غيّرت الشاشات طريقة قراءتنا؛ فكثيرٌ منا صار يتنقّل بين العناوين والفقرات بسرعة، يلتقط كلمة من هنا وجملة من هناك، ثم ينتقل إلى نص آخر قبل أن يُتمّ الأول. ولا ضَير في هذا الأسلوب حين نبحث عن معلومة محددة، كموعد رحلة أو رقم هاتف، لكن المشكلة تبدأ حين يصبح عادةً نقرأ بها كل شيء. فالنصوص التي تحمل أفكارًا مركّبة، كالمقالات العلمية والأعمال الأدبية، تحتاج إلى قراءة متأنية يتوقف فيها القارئ ليربط فكرة بأخرى، ويسأل، ويوازن. وتلك مهارة لا تُكتسب مرة واحدة، بل تُصان بالممارسة؛ فمن هجرها طويلًا قد يجد صعوبة في العودة إليها. لذلك ينصح بعض التربويين بتخصيص وقت يومي للقراءة المتأنية بعيدًا عن المشتّتات.$q$, $q$["عند البحث عن معلومة محددة","عند قراءة الأعمال الأدبية","عند دراسة المقالات العلمية","عند الرغبة في ربط الأفكار"]$q$::jsonb, 60, array[$q$استيعاب المقروء$q$, $q$تفاصيل$q$]::text[], (select s.id from public.question_sources s where s.slug = 'jazira-original'), null, null, 'ar', false, true),
  ('av-056', 'aptitude', 'verbal', 'reading-comprehension', 2, $q$ما معنى كلمة «ضَير» في قول الكاتب «ولا ضَير في هذا الأسلوب»؟$q$, $q$غيّرت الشاشات طريقة قراءتنا؛ فكثيرٌ منا صار يتنقّل بين العناوين والفقرات بسرعة، يلتقط كلمة من هنا وجملة من هناك، ثم ينتقل إلى نص آخر قبل أن يُتمّ الأول. ولا ضَير في هذا الأسلوب حين نبحث عن معلومة محددة، كموعد رحلة أو رقم هاتف، لكن المشكلة تبدأ حين يصبح عادةً نقرأ بها كل شيء. فالنصوص التي تحمل أفكارًا مركّبة، كالمقالات العلمية والأعمال الأدبية، تحتاج إلى قراءة متأنية يتوقف فيها القارئ ليربط فكرة بأخرى، ويسأل، ويوازن. وتلك مهارة لا تُكتسب مرة واحدة، بل تُصان بالممارسة؛ فمن هجرها طويلًا قد يجد صعوبة في العودة إليها. لذلك ينصح بعض التربويين بتخصيص وقت يومي للقراءة المتأنية بعيدًا عن المشتّتات.$q$, $q$["فائدة","غرابة","ضرر","صعوبة"]$q$::jsonb, 60, array[$q$استيعاب المقروء$q$, $q$معنى كلمة$q$]::text[], (select s.id from public.question_sources s where s.slug = 'jazira-original'), null, null, 'ar', false, true),
  ('av-057', 'aptitude', 'verbal', 'reading-comprehension', 3, $q$ما موقف الكاتب من القراءة السريعة كما يُفهم من النص؟$q$, $q$غيّرت الشاشات طريقة قراءتنا؛ فكثيرٌ منا صار يتنقّل بين العناوين والفقرات بسرعة، يلتقط كلمة من هنا وجملة من هناك، ثم ينتقل إلى نص آخر قبل أن يُتمّ الأول. ولا ضَير في هذا الأسلوب حين نبحث عن معلومة محددة، كموعد رحلة أو رقم هاتف، لكن المشكلة تبدأ حين يصبح عادةً نقرأ بها كل شيء. فالنصوص التي تحمل أفكارًا مركّبة، كالمقالات العلمية والأعمال الأدبية، تحتاج إلى قراءة متأنية يتوقف فيها القارئ ليربط فكرة بأخرى، ويسأل، ويوازن. وتلك مهارة لا تُكتسب مرة واحدة، بل تُصان بالممارسة؛ فمن هجرها طويلًا قد يجد صعوبة في العودة إليها. لذلك ينصح بعض التربويين بتخصيص وقت يومي للقراءة المتأنية بعيدًا عن المشتّتات.$q$, $q$["رفضها رفضًا مطلقًا في جميع المواقف","تفضيلها على القراءة المتأنية في معظم النصوص","قبولها في قراءة الأعمال الأدبية دون المقالات العلمية","قبولها في مواضع محددة مع التحذير من جعلها عادة"]$q$::jsonb, 60, array[$q$استيعاب المقروء$q$, $q$موقف الكاتب$q$]::text[], (select s.id from public.question_sources s where s.slug = 'jazira-original'), null, null, 'ar', false, true),
  ('av-058', 'aptitude', 'verbal', 'reading-comprehension', 1, $q$بحسب النص، ما حقيقة الشعاب المرجانية؟$q$, $q$تبدو الشعاب المرجانية للناظر كأنها صخور ملوّنة في قاع البحر، لكنها في الحقيقة مستعمرات من كائنات حية دقيقة تُفرز هياكل كلسية تتراكم عبر السنين. وتعيش في أنسجة المرجان طحالب مجهرية تمدّه بجزء كبير من غذائه وتمنحه ألوانه الزاهية، في علاقة ينتفع فيها الطرفان. فإذا ارتفعت حرارة الماء فوق ما يحتمله المرجان مدةً طويلة، طرد تلك الطحالب ففقد لونه وابيضّ، وهي ظاهرة تُعرف بابيضاض المرجان؛ فإن لم تعد الظروف إلى طبيعتها سريعًا فقد يموت. وتكتسب الشعاب أهمية تتجاوز جمالها، فهي مأوى لأعداد هائلة من الأسماك، وحاجز طبيعي يكسر حدّة الأمواج قبل بلوغها الشواطئ.$q$, $q$["صخور ملوّنة في قاع البحر","نباتات بحرية تنمو على الصخور","مستعمرات من كائنات حية دقيقة","طحالب مجهرية تعيش في الماء"]$q$::jsonb, 60, array[$q$استيعاب المقروء$q$, $q$تفاصيل$q$]::text[], (select s.id from public.question_sources s where s.slug = 'jazira-original'), null, null, 'ar', false, true),
  ('av-059', 'aptitude', 'verbal', 'reading-comprehension', 2, $q$ما سبب ابيضاض المرجان كما ورد في النص؟$q$, $q$تبدو الشعاب المرجانية للناظر كأنها صخور ملوّنة في قاع البحر، لكنها في الحقيقة مستعمرات من كائنات حية دقيقة تُفرز هياكل كلسية تتراكم عبر السنين. وتعيش في أنسجة المرجان طحالب مجهرية تمدّه بجزء كبير من غذائه وتمنحه ألوانه الزاهية، في علاقة ينتفع فيها الطرفان. فإذا ارتفعت حرارة الماء فوق ما يحتمله المرجان مدةً طويلة، طرد تلك الطحالب ففقد لونه وابيضّ، وهي ظاهرة تُعرف بابيضاض المرجان؛ فإن لم تعد الظروف إلى طبيعتها سريعًا فقد يموت. وتكتسب الشعاب أهمية تتجاوز جمالها، فهي مأوى لأعداد هائلة من الأسماك، وحاجز طبيعي يكسر حدّة الأمواج قبل بلوغها الشواطئ.$q$, $q$["تراكم الهياكل الكلسية عبر السنين","طرده الطحالب بسبب ارتفاع حرارة الماء","اصطدام الأمواج العنيفة بالشعاب قبل بلوغها الشواطئ","كثرة الأسماك التي تأوي إلى الشعاب"]$q$::jsonb, 60, array[$q$استيعاب المقروء$q$, $q$سبب ونتيجة$q$]::text[], (select s.id from public.question_sources s where s.slug = 'jazira-original'), null, null, 'ar', false, true),
  ('av-060', 'aptitude', 'verbal', 'reading-comprehension', 3, $q$يُفهم من النص أن المرجان قد يموت إذا طال ابيضاضه لأنه:$q$, $q$تبدو الشعاب المرجانية للناظر كأنها صخور ملوّنة في قاع البحر، لكنها في الحقيقة مستعمرات من كائنات حية دقيقة تُفرز هياكل كلسية تتراكم عبر السنين. وتعيش في أنسجة المرجان طحالب مجهرية تمدّه بجزء كبير من غذائه وتمنحه ألوانه الزاهية، في علاقة ينتفع فيها الطرفان. فإذا ارتفعت حرارة الماء فوق ما يحتمله المرجان مدةً طويلة، طرد تلك الطحالب ففقد لونه وابيضّ، وهي ظاهرة تُعرف بابيضاض المرجان؛ فإن لم تعد الظروف إلى طبيعتها سريعًا فقد يموت. وتكتسب الشعاب أهمية تتجاوز جمالها، فهي مأوى لأعداد هائلة من الأسماك، وحاجز طبيعي يكسر حدّة الأمواج قبل بلوغها الشواطئ.$q$, $q$["يفقد جزءًا كبيرًا من غذائه","يفقد لونه الذي يحميه من الحرارة","تتحطّم هياكله بفعل الأمواج","تهجره الأسماك التي تغذّيه"]$q$::jsonb, 60, array[$q$استيعاب المقروء$q$, $q$استنتاج$q$]::text[], (select s.id from public.question_sources s where s.slug = 'jazira-original'), null, null, 'ar', false, true)
on conflict (key) do update set
  exam = excluded.exam,
  section = excluded.section,
  topic = excluded.topic,
  difficulty = excluded.difficulty,
  stem = excluded.stem,
  passage = excluded.passage,
  choices = excluded.choices,
  time_limit_seconds = excluded.time_limit_seconds,
  tags = excluded.tags,
  source_id = excluded.source_id,
  source_ref = excluded.source_ref,
  year = excluded.year,
  language = excluded.language,
  is_premium = excluded.is_premium,
  is_active = excluded.is_active
where (q.exam, q.section, q.topic, q.difficulty, q.stem, q.passage, q.choices, q.time_limit_seconds, q.tags, q.source_id, q.source_ref, q.year, q.language, q.is_premium, q.is_active)
  is distinct from (excluded.exam, excluded.section, excluded.topic, excluded.difficulty, excluded.stem, excluded.passage, excluded.choices, excluded.time_limit_seconds, excluded.tags, excluded.source_id, excluded.source_ref, excluded.year, excluded.language, excluded.is_premium, excluded.is_active);

insert into public.question_keys as k (question_id, correct_index, explanation)
select q.id, v.correct_index, v.explanation
  from (values
    ('av-001', 2, $q$العلاقة: شيء ومكان تُجمع فيه أمثاله وتُحفظ؛ فالكتب تُجمع في المكتبة، واللوحات تُجمع في المتحف وتُعرض. أما «رسّام : لوحة» فصانع ونتاجه، و«ورق : كتاب» مادة وما يُصنع منها، و«فرشاة : ألوان» أداة وما تُستعمل معه.$q$),
    ('av-002', 2, $q$العلاقة: صاحب مهنة ومكان عمله؛ فالطبيب يعمل في المستشفى كما يعمل المعلّم في المدرسة. أما «مزارع : محصول» فصاحب مهنة ونتاج عمله، و«قاضٍ : عدالة» صاحب مهنة وغايته، و«طالب : كتاب» مستخدِم وأداته.$q$),
    ('av-003', 3, $q$العلاقة: حاجة وما يسدّها؛ فالعطش يزول بشرب الماء، والجوع يزول بتناول الطعام. أما «مطر : سحاب» فشيء ومصدره، و«نوم : سرير» فعل ومكانه، و«برد : شتاء» صفة والفصل الذي تغلب فيه.$q$),
    ('av-004', 1, $q$العلاقة: كائن ومادة غذائية يُنتجها ينتفع بها الإنسان؛ فالنحلة تُنتج العسل، والبقرة تُنتج الحليب. أما «طائر : عُش» فكائن ومسكنه الذي يبنيه لا غذاء يُنتجه، و«حصان : سرج» حيوان وأداة تُوضع عليه، و«أسد : زئير» حيوان وصوته.$q$),
    ('av-005', 0, $q$العلاقة تضادّ؛ فالجبان عكس الشجاع، والبخيل عكس الكريم. أما الأزواج الأخرى فكلماتها متقاربة المعنى، فعلاقتها ترادف أو تقارب لا تضادّ.$q$),
    ('av-006', 0, $q$العلاقة: طور أول وما يؤول إليه بعد النمو؛ فالبذرة تنمو فتصير شجرة، واليرقة تتحوّل فتصير فراشة. أما «غصن : ورقة» فجزء وما ينبت عليه، و«جذر : تربة» جزء ومكانه، و«زهرة : رحيق» شيء وما يحتويه.$q$),
    ('av-007', 3, $q$العلاقة: أداة وما تقيسه؛ فالمسطرة يُقاس بها الطول، والساعة يُقاس بها الزمن. أما «قلم : ورقة» فأداة وما يُكتب عليه، و«مصباح : كهرباء» جهاز ومصدر طاقته، و«مفتاح : قفل» أداة وما تفتحه.$q$),
    ('av-008', 2, $q$العلاقة: فرد والجماعة التي ينتمي إليها؛ فالجندي فرد في الجيش، واللاعب فرد في الفريق. أما «ربّان : سفينة» فقائد وما يقوده، و«طبيب : مريض» صاحب مهنة ومن يخدمه، و«شجرة : ثمرة» مصدر وما ينتج منه.$q$),
    ('av-009', 1, $q$العلاقة: بداية الشيء ونهايته؛ فالمقدّمة أول النص والخاتمة آخره، والشروق أول النهار والغروب آخره. أما «فصل : كتاب» فجزء وكل، و«تمهيد : توطئة» مترادفان، و«ليل : نجوم» زمن وما يظهر فيه.$q$),
    ('av-010', 0, $q$العلاقة: سبب ونتيجته؛ فالإسراف يؤدي إلى الفقر، والإهمال يؤدي إلى الرسوب. أما «دواء : مرض» فعلاج وما يعالجه، و«غيم : سماء» شيء ومكانه، و«صبر : تحمّل» متقاربان في المعنى.$q$),
    ('av-011', 3, $q$العلاقة: صاحب حرفة والمادة الخام التي يعمل بها؛ فالنجّار يصنع من الخشب، والخيّاط يصنع من القماش. أما «بنّاء : جدار» فصاحب حرفة ونتاج عمله، و«حدّاد : مطرقة» صاحب حرفة وأداته، و«طيّار : طائرة» قائد وما يقوده.$q$),
    ('av-012', 0, $q$العلاقة تدرّج في الشدّة داخل الظاهرة نفسها؛ فالرذاذ مطر خفيف والوابل مطر غزير، والنسيم ريح لطيفة والإعصار ريح عنيفة. أما «مطر : غيث» فمتقاربان في المعنى، و«ريح : شراع» قوة وما تحرّكه، و«سحاب : ضباب» ظاهرتان متشابهتان لا تدرّج بينهما في الشدّة.$q$),
    ('av-013', 1, $q$العلاقة: صاحب صفة والرذيلة المنتفية عنه؛ فالمتواضع بعيد عن الغرور، والكريم بعيد عن الشُّحّ أي البخل. أما «عالِم : معرفة» و«شجاع : إقدام» فصاحب صفة وما يتّصف به فعلًا، وهي عكس العلاقة المطلوبة، و«مريض : دواء» حالة وعلاجها.$q$),
    ('av-014', 1, $q$العلاقة: رسم مصغّر يمثّل شيئًا ويبيّن أجزاءه؛ فالخريطة تمثّل المدينة وشوارعها، والمخطّط يمثّل المبنى وغرفه. أما «تمثال : حجر» فعمل فني ومادته، و«صورة : ألوان» عمل ووسيلة تنفيذه، و«بوصلة : اتجاه» أداة وما تدلّ عليه.$q$),
    ('av-015', 3, $q$أداة الاستدراك «بل» تنفي ما قبلها وتُثبت ما بعدها في الأمر نفسه، وما بعدها يبيّن سبب التأخّر وهو العطل المفاجئ، فالمنفيّ يجب أن يكون سببًا آخر يقابله، وهو تقصير السائق. أما الإزعاج والنُّدرة وطول التأخّر فلا تبيّن سببه، فلا يقوم بينها وبين «نتيجة عطل» تقابل.$q$),
    ('av-016', 0, $q$عبارة «يخشى أن تخونه ذاكرته» تدل على الخوف، والوَجِل هو الخائف، فهو المناسب للسياق. أما المزهوّ فالمعجب بنفسه، والمتكاسل المتثاقل، والمبتهج المسرور، وكلها لا تتّسق مع الخشية.$q$),
    ('av-017', 2, $q$عبارة «حين يتخلّى عن المرء كثيرٌ من الناس» تصف وقت الضيق، والناس يتخلّون عن المرء في الشدّة لا في الرخاء أو النجاح أو الفراغ، فالصديق الحقيقي يظهر في وقت الشدّة.$q$),
    ('av-018', 0, $q$ما يخشاه المزارع هو ضياع الماء قبل وصوله إلى الجذور، وحرارة الشمس تُضيّع الماء بتبخيره، فالمناسب «تُبخِّر». أما الإضاءة والتدفئة والتلوين فلا تُفقد النبات ماءه.$q$),
    ('av-019', 3, $q$وصف الوقت بأنه «لا يُعوَّض»، وعبارة «مهما حاولنا استرجاعه»، يعنيان أن ما يذهب منه لا يمكن استرداده، فالمناسب «لا يعود». أما «لا يتوقّف» فيصف جريان الوقت لا ما مضى منه، و«لا يُهدَر» لا صلة له بالاسترجاع، و«لا يُنسى» يناقض العجز عن الاسترجاع الذي تدل عليه «مهما».$q$),
    ('av-020', 1, $q$عبارة «على الرغم من» تدل على أن ما بعدها كان عائقًا تحقّق الإنجاز مع وجوده، والعائق المناسب هو قلّة الموارد أي «شُحّها». أما الوفرة والتنوّع والجودة فأسباب تُعين على الإنجاز، فلا يصحّ أن تُسبَق بعبارة «على الرغم من».$q$),
    ('av-021', 2, $q$«لا يكفي» تعني أن الصفة الأولى مطلوبة لكنها غير كافية، فلا بدّ أن تكون صفة محمودة كالجِدّة، ثم تأتي الصفة المكمِّلة وهي القابلية للتطبيق. أما القِدم والتكرار والغموض فليست صفات محمودة في الفكرة حتى يُقال إنها «لا تكفي».$q$),
    ('av-022', 3, $q$التركيب «لم يكتفِ… بل» ينقل من عمل بسيط هو النقل إلى عمل أعمق منه، وعبارة «بيَّن ما لها وما عليها» تدل على الفحص والتمحيص، فالمناسب «دقّق». أما «تسرّع» فيناقض التمحيص الذي تدل عليه تلك العبارة، و«تهاون» و«زهِد» لا يتّسقان معه.$q$),
    ('av-023', 2, $q$الجملة تقوم على التشبيه بأداة «كما»، فما يقابل تمرين العضلات هو تمرين العقل، أي إعماله بالتفكير المستمر. أما الراحة والغذاء والعزلة فلا تقابل التمرين في الشطر الأول.$q$),
    ('av-024', 1, $q$الحديث قصير («دقائق معدودة») ومع ذلك وافٍ بالفكرة، وهذا هو الإيجاز. أما «مُسهبًا» فيناقض قِصر الحديث، و«متلعثمًا» و«مُبهَمًا» يناقضان إيصال الفكرة كاملة.$q$),
    ('av-025', 2, $q$التركيب «على الرغم من أنها بدت… فإنها في الحقيقة…» يقابل بين المظهر والحقيقة، والحقيقة أنها مدروسة، فالمظهر المقابل أنها ارتجالية أي بلا تحضير. أما «متأنّية» فتكرّر معنى الحقيقة ولا تقابلها، و«حصيفة» و«نافذة» لا تقابلان «دراسة متأنية».$q$),
    ('av-026', 3, $q$الشطر الثاني يعلّل النهي بذكر الغلاف، فالفراغ الأول «غلافه»، والتعليل يقتضي أن يكون المضمون خلاف ما يوحي به الغلاف الأنيق، أي «ضحل المضمون». أما «رصين المضمون» فيجعل الغلاف والمضمون متّفقين، فيصحّ الحكم بالغلاف ويبطل النهي.$q$),
    ('av-027', 0, $q$احتراق الطعام واسوداد القِدر وإسراع الجميع إلى فتح النوافذ كلها تدل على رائحة كريهة، فكلمة «زكيّة» أي طيّبة تناقض السياق، وصوابها «كريهة».$q$),
    ('av-028', 2, $q$اشتداد البرد وتساقط الثلوج وإشعال المدافئ تقتضي ارتداء ملابس تحفظ الدفء، فكلمة «الخفيفة» تناقض السياق، وصوابها «الثقيلة».$q$),
    ('av-029', 0, $q$أمانة التاجر وإقبال الناس على الشراء منه وتوصيتهم به غيرهم كلها تدل على الثقة به، فكلمة «يشكّ» تناقض السياق، وصوابها «يثق».$q$),
    ('av-030', 2, $q$البرق يُحدث ضوءًا شديدًا مفاجئًا يدفع إلى إغماض العينين، فالسبب شدّة الضوء لا الظلام؛ فكلمة «الظلام» خطأ سياقي، وصوابها «الضوء» أو «الوهج».$q$),
    ('av-031', 3, $q$قلّة الأمطار تجعل البقاء للنباتات التي تحافظ على الماء، ولذلك تختزنه في سيقانها، والإسراف في استهلاكه يناقض ذلك؛ فكلمة «تُسرف» خطأ سياقي، وصوابها «تقتصد».$q$),
    ('av-032', 1, $q$الحِلم والاستماع إلى جميع الأطراف قبل القضاء بينهم يدلّان على التأنّي، فكلمة «يتسرّع» تناقض السياق، وصوابها «يتأنّى».$q$),
    ('av-033', 1, $q$الازدحام يسبّب التأخّر لا الالتزام بالمواعيد، ويؤكد ذلك أن الشركات اتخذت إجراءً «للحدّ من التأخّر»؛ فكلمة «التزام» خطأ سياقي، وصوابها «إخلال» أي إخلال الموظفين بمواعيد أعمالهم، ويصحّ «تأخّر» مع تغيير حرف الجرّ: تأخّر الموظفين عن مواعيد أعمالهم.$q$),
    ('av-034', 0, $q$تثبيت الجذور للتربة وحمايتها من الانجراف فوائد تقاوم التصحّر ولا تسرّعه، و«أنجع الوسائل» لا تُقال إلا في علاج مشكلة؛ فكلمة «لتسريع» تناقض السياق، وصوابها «لمكافحة».$q$),
    ('av-035', 0, $q$قلّة ما يستنشقه المتسلّقون من أكسجين وحملُهم أسطواناتِه لمواصلة الصعود يدلّان على أن التنفّس في القمم الشاهقة صعب، فكلمة «يسهُل» تناقض السياق، وصوابها «يصعُب». ولا يصحّ أن يكون الخطأ في «يخِفّ»، لأن خفّة الهواء هي سبب قلّة الأكسجين المستنشَق.$q$),
    ('av-036', 3, $q$الجملة تنقل مقياس الثقافة من الكمّ (عدد الكتب المقتناة) إلى الانتفاع بها، والانتفاع يكون بالاستيعاب والتطبيق لا بالإهمال؛ فكلمة «يُهمله» خطأ سياقي، وصوابها «يُطبّقه» أو «يوظّفه».$q$),
    ('av-037', 3, $q$تضاؤل اليقين وكثرة الأسئلة نتيجتان لاتّساع المعرفة، والتعليل بعد «لأنّ» يجب أن يتّسق معهما، فالعلم يفتح أبواب التساؤل لا الجزم؛ فكلمة «الجزم» خطأ سياقي، وصوابها «التساؤل». ولا يكون الخطأ في «تضاءل»، لأن عبارة «وكثرت أسئلته» تدل على تراجع اليقين لا ازدياده.$q$),
    ('av-038', 2, $q$«حُبور» و«سرور» و«بهجة» كلمات متقاربة المعنى تدل على الفرح، أما «أسى» فتدل على الحزن، فهي الكلمة المختلفة.$q$),
    ('av-039', 0, $q$الأسد والنمر والفهد حيوانات مفترسة تتغذّى على اللحوم، أما الغزال فحيوان عاشب يتغذّى على النبات، فهو الكلمة المختلفة.$q$),
    ('av-040', 3, $q$الذهب والفضة والنحاس معادن، أما الخشب فمادة نباتية مصدرها الأشجار، فهو الكلمة المختلفة.$q$),
    ('av-041', 2, $q$«شجاعة» و«إقدام» و«جسارة» مترادفات تدل على الجرأة وعدم الخوف، أما «حكمة» فتدل على وضع الأمور في مواضعها، وهي صفة محمودة لكنها من معنى آخر.$q$),
    ('av-042', 3, $q$«قرأ» و«طالع» و«تصفّح» أفعال تدل على تلقّي المكتوب والنظر فيه، أما «كتب» فتدل على إنتاج المكتوب، فهي الكلمة المختلفة.$q$),
    ('av-043', 1, $q$السيف والرمح والخنجر أسلحة يُهاجَم بها، أما الدرع فيُتّقى به الضرب، أي أنه للدفاع لا للهجوم، فهو الكلمة المختلفة.$q$),
    ('av-044', 1, $q$«يتأمّل» و«يتدبّر» و«يتفكّر» تدل على إعمال العقل في أمرٍ للنظر فيه وفهمه، أما «يتذكّر» فتدل على استحضار ما مضى في الذاكرة، فهي الكلمة المختلفة.$q$),
    ('av-045', 3, $q$«السُّهاد» و«الأرَق» و«السَّهَر» كلها تدل على ذهاب النوم ليلًا، أما «الرُّقاد» فمعناه النوم نفسه، فهو ضدّها والكلمة المختلفة.$q$),
    ('av-046', 0, $q$يعرض النص منافع النخلة وقدرتها على الصمود قديمًا، ثم يبيّن استمرار أهميتها في العصر الحديث، فالفكرة الرئيسة مكانتها في الزمنين. أما الخيارات الأخرى فتفاصيل جزئية وردت في سياق هذه الفكرة.$q$),
    ('av-047', 1, $q$ينصّ النص على أن «قدرتها على تحمّل الحرارة وملوحة التربة جعلتها رفيقة الإنسان»، ويقرّر قبل ذلك أن المنافع «لم تكن وحدها سرّ مكانتها»، فتسقيف البيوت وفتل الحبال منافع لا سبب للمرافقة. أما التصدير فأمر حديث، والحاجة إلى ماء كثير لم ترد في النص.$q$),
    ('av-048', 0, $q$«القوت المحلي» ما يأكله أهل البلد، و«السلعة التي يعرفها العالم» ما يُتاجَر به في أسواق بعيدة، فالعبارة تصف تجاوز التمور حدود الاستهلاك المحلي إلى التجارة العالمية. ولم يذكر النص فقدان قيمتها الغذائية، ولا زراعتها في بلدان أخرى، ولا توقّف أهلها عن أكلها.$q$),
    ('av-049', 1, $q$يذكر النص أن الدماغ في أثناء النوم «يُعيد ترتيب ما اكتسبه خلال اليوم، فيُثبّت المهمّ منه في الذاكرة طويلة المدى». أما التوقف عن العمل فنفاه النص صراحة، ولم يذكر أن النوم يمحو شيئًا، ولا أنه يُثبّت كل ما اكتُسب دون تمييز، بل خصّ بالتثبيت المهمَّ منه.$q$),
    ('av-050', 1, $q$الحشو إدخال كثير من الشيء في حيّز ضيق، والنص يقابل هذه العبارة بـ«توزيع المراجعة على أيام متعددة»، فالمقصود تكديس المعلومات في وقت قصير. أما توزيع المراجعة والنوم الكافي فهما الأسلوب المقابل الذي يفضّله المختصون.$q$),
    ('av-051', 3, $q$ينصّ النص على أن من يحرم نفسه النوم «قد يحفظ كمًّا كبيرًا من المعلومات… لكنه قد يجد صعوبة في استرجاعها»، فكثرة المحفوظ لا تضمن سهولة الاسترجاع. أما القول إن السهر يمنع الحفظ مطلقًا، أو إن النوم وحده يضمن التفوق، فتعميم لم يقله النص، والقول إن السهر يُضعف الحفظ أكثر من الاسترجاع عكسُ ما يُفهم منه، إذ يبقى الحفظ ممكنًا ويصعب الاسترجاع.$q$),
    ('av-052', 2, $q$ينصّ النص في مطلعه على أن طول ساعات السطوع الشمسي «يجعلها من أنسب البيئات». أما الحرارة والغبار فذكرهما النص تحدّيين لا ميزتين، ولم يذكر وفرة الماء، بل ذكر أن المهندسين يطوّرون أنظمة تنظيف تستهلك قليلًا منه أو لا تستهلكه.$q$),
    ('av-053', 1, $q$أداة الاستدراك «غير أنّ» تنقل الكلام إلى ما يخالف ما قبله؛ فقبلها عرض النص مزايا الصحراء والألواح، وبعدها ذكر الغبار والحرارة بوصفهما صعوبتين. فهي لا تؤكّد المزايا السابقة بل تخالفها، ولا تلخّص النص كله لأنها تمهّد لجزء واحد منه هو التحديات، أما الحلول فجاءت بعد ذلك في الجملة الأخيرة.$q$),
    ('av-054', 2, $q$كلمة «فعلًا» تُشعر بأن التحوّل لم يكتمل بعد، لأن الغبار والحرارة يحولان دون استثمار الشمس استثمارًا كاملًا، فوفرة الشمس وحدها لا تكفي. أما القول إن الألواح لا تُنتج شيئًا فمبالغة، إذ يقول النص إن الغبار «يُضعف» الإنتاج، ولم يتحدث عن الأسعار ولا عن نجاح كامل.$q$),
    ('av-055', 0, $q$يقول الكاتب «ولا ضَير في هذا الأسلوب حين نبحث عن معلومة محددة». أما المقالات العلمية والأعمال الأدبية وربط الأفكار فيرى أنها تحتاج إلى قراءة متأنية.$q$),
    ('av-056', 2, $q$الضَّير هو الضرر، والسياق يؤكد ذلك؛ فالكاتب يُجيز الأسلوب في موضع محدد ثم يقول «لكن المشكلة تبدأ…»، أي لا ضرر فيه هنا، وإنما يقع الضرر حين يصير عادة.$q$),
    ('av-057', 3, $q$أجاز الكاتب القراءة السريعة عند البحث عن معلومة محددة، ثم حذّر من أن تصبح عادة نقرأ بها كل شيء، فموقفه قبول مقيّد لا رفض مطلق. ودعوته إلى تخصيص وقت يومي للقراءة المتأنية تنفي أن يفضّل القراءة السريعة، وقد جعل المقالات العلمية والأعمال الأدبية معًا مما يحتاج إلى قراءة متأنية، فلا يقبلها في أحدهما دون الآخر.$q$),
    ('av-058', 2, $q$يقول النص إنها تبدو كالصخور «لكنها في الحقيقة مستعمرات من كائنات حية دقيقة». أما الصخور فهي ما تبدو عليه لا حقيقتها، والطحالب كائنات تعيش في أنسجتها وليست هي الشعاب نفسها. ولم يصفها النص بأنها نباتات، فالمرجان حيوانات دقيقة تعيش في مستعمرات وتُفرز هياكلها الكلسية، لا نباتات بحرية كما قد يُظنّ.$q$),
    ('av-059', 1, $q$يذكر النص أن الحرارة إذا ارتفعت فوق ما يحتمله المرجان مدة طويلة «طرد تلك الطحالب ففقد لونه وابيضّ»، والطحالب هي التي تمنحه ألوانه. أما الهياكل الكلسية والأمواج والأسماك فذُكرت في سياقات أخرى لا علاقة لها بالابيضاض.$q$),
    ('av-060', 0, $q$الجواب يأتي من ربط معلومتين في النص: فالطحالب «تمدّه بجزء كبير من غذائه»، والابيضاض يعني طردها، فإذا طال حُرم المرجان هذا الغذاء، وهذا ما يفسّر موته. أما فقدان اللون فنتيجة للابيضاض لا سبب للموت، ولم يذكر النص أن اللون يحميه، ولا أن الأمواج تحطّم هياكله، ولا أن الأسماك تغذّيه.$q$)
  ) as v (key, correct_index, explanation)
  join public.questions q on q.key = v.key
on conflict (question_id) do update set
  correct_index = excluded.correct_index,
  explanation   = excluded.explanation
where (k.correct_index, k.explanation) is distinct from (excluded.correct_index, excluded.explanation);

