  ('am-031', 'achievement', 'math', 'statistics-probability', 2, $q$تتوزع درجات الطلاب في أحد الاختبارات توزيعًا طبيعيًا متوسطه 70 وانحرافه المعياري 5. ما النسبة المئوية التقريبية للطلاب الذين تقع درجاتهم بين 60 و80؟$q$, null, $q$["47.5%","68%","95%","99.7%"]$q$::jsonb, 75, array[$q$التوزيع الطبيعي$q$, $q$القاعدة التجريبية$q$]::text[], (select s.id from public.question_sources s where s.slug = 'jazira-original'), null, null, 'ar', false, true),
  ('am-032', 'achievement', 'math', 'statistics-probability', 3, $q$كيس فيه 10 كرات متماثلة عدا اللون، منها 4 كرات حمراء و6 كرات زرقاء. سُحبت منه كرتان عشوائيًا، واحدة تلو الأخرى دون إرجاع. ما احتمال أن تكون الكرتان مختلفتين في اللون؟$q$, null, $q$["4/15","7/15","12/25","8/15"]$q$::jsonb, 90, array[$q$الاحتمال$q$, $q$السحب دون إرجاع$q$]::text[], (select s.id from public.question_sources s where s.slug = 'jazira-original'), null, null, 'ar', false, true),
  ('am-033', 'achievement', 'math', 'sequences', 1, $q$متتابعة حسابية حدها الأول 5 وأساسها 3. ما حدها العشرون؟$q$, null, $q$["59","60","62","65"]$q$::jsonb, 60, array[$q$المتتابعات الحسابية$q$, $q$الحد النوني$q$]::text[], (select s.id from public.question_sources s where s.slug = 'jazira-original'), null, null, 'ar', false, true),
  ('am-034', 'achievement', 'math', 'sequences', 1, $q$ما الحد الثامن في المتتابعة الهندسية: 3، 6، 12، 24، ...؟$q$, null, $q$["48","192","384","768"]$q$::jsonb, 60, array[$q$المتتابعات الهندسية$q$, $q$الحد النوني$q$]::text[], (select s.id from public.question_sources s where s.slug = 'jazira-original'), null, null, 'ar', false, true),
  ('am-035', 'achievement', 'math', 'sequences', 2, $q$ما مجموع المتسلسلة الحسابية: 3 + 7 + 11 + ... + 79؟$q$, null, $q$["779","820","861","1640"]$q$::jsonb, 75, array[$q$المتسلسلات الحسابية$q$, $q$المجموع$q$]::text[], (select s.id from public.question_sources s where s.slug = 'jazira-original'), null, null, 'ar', false, true),
  ('am-036', 'achievement', 'math', 'sequences', 3, $q$متتابعة هندسية حدها الثالث 12 وحدها السادس 96. ما مجموع حدودها الخمسة الأولى؟$q$, null, $q$["93","96","186","189"]$q$::jsonb, 90, array[$q$المتسلسلات الهندسية$q$, $q$المجموع$q$]::text[], (select s.id from public.question_sources s where s.slug = 'jazira-original'), null, null, 'ar', false, true),
  ('am-037', 'achievement', 'math', 'matrices', 1, $q$إذا كانت A مصفوفة من الرتبة 2 × 2، عناصر صفها الأول 3 و2، وعناصر صفها الثاني 1 و4، فما قيمة det(A)؟$q$, null, $q$["−10","7","10","14"]$q$::jsonb, 60, array[$q$المحددات$q$, $q$المصفوفات$q$]::text[], (select s.id from public.question_sources s where s.slug = 'jazira-original'), null, null, 'ar', false, true),
  ('am-038', 'achievement', 'math', 'matrices', 2, $q$إذا كانت A وB مصفوفتين من الرتبة 2 × 2، عناصر الصف الأول من A هي 1 و2، وعناصر صفها الثاني 0 و3، وعناصر الصف الأول من B هي 2 و0، وعناصر صفها الثاني 1 و1، فما العنصر الواقع في الصف الثاني والعمود الأول من المصفوفة AB؟$q$, null, $q$["0","1","2","3"]$q$::jsonb, 75, array[$q$ضرب المصفوفات$q$]::text[], (select s.id from public.question_sources s where s.slug = 'jazira-original'), null, null, 'ar', false, true),
