  passage = excluded.passage,
  choices = excluded.choices,
  time_limit_seconds = excluded.time_limit_seconds,
  tags = excluded.tags,
  source_id = excluded.source_id,
  source_ref = excluded.source_ref,
  year = excluded.year,
  language = excluded.language,
  is_premium = excluded.is_premium,
  is_active = excluded.is_active
where (q.exam, q.section, q.topic, q.difficulty, q.stem, q.passage, q.choices, q.time_limit_seconds, q.tags, q.source_id, q.source_ref, q.year, q.language, q.is_premium, q.is_active)
  is distinct from (excluded.exam, excluded.section, excluded.topic, excluded.difficulty, excluded.stem, excluded.passage, excluded.choices, excluded.time_limit_seconds, excluded.tags, excluded.source_id, excluded.source_ref, excluded.year, excluded.language, excluded.is_premium, excluded.is_active);

insert into public.question_keys as k (question_id, correct_index, explanation)
select q.id, v.correct_index, v.explanation
  from (values
    ('am-001', 1, $q$للقيمة المطلقة حالتان: 2x − 3 = 7 ومنها x = 5، أو 2x − 3 = −7 ومنها 2x = −4، أي x = −2؛ فمجموعة الحل {5, −2}.$q$),
    ('am-002', 3, $q$قوى i تتكرر كل أربع قوى، وباقي قسمة 23 على 4 يساوي 3؛ لذا i²³ = i³ = i² × i = −i.$q$),
    ('am-003', 1, $q$يكون للمعادلة جذران متساويان عندما يساوي المميز صفرًا: k² − 4 × 1 × 9 = 0، أي k² = 36، ومنه k = ±6، والقيمة الموجبة 6.$q$),
    ('am-004', 2, $q$حسب نظرية الباقي، الباقي يساوي p(2) = 8 − 8 + 2k + 4 = 2k + 4، وبمساواته بالعدد 10 نجد 2k = 6، أي k = 3.$q$),
    ('am-005', 3, $q$من العلاقة بين الجذور والمعاملات: α + β = 6/2 = 3، وαβ = 1/2. ولأن α² + β² = (α + β)² − 2αβ، فإن α² + β² = 9 − 1 = 8.$q$),
    ('am-006', 2, $q$بالتعويض: f(−2) = 2(−2)² − 3 = 2 × 4 − 3 = 5، مع الانتباه إلى أن (−2)² = 4 عدد موجب.$q$),
    ('am-007', 3, $q$لا يُعرَّف الجذر التربيعي في الأعداد الحقيقية إلا لمقدار غير سالب، لذا x − 4 ≥ 0، أي x ≥ 4. ويدخل العدد 4 في المجال لأن √0 = 0.$q$),
    ('am-008', 2, $q$بخاصية الضرب للوغاريتمات: log₂((x − 1)(x + 1)) = 3، أي x² − 1 = 2³ = 8، ومنه x = ±3، ولأن تعريف اللوغاريتمين يشترط x − 1 > 0 وx + 1 > 0 (أي x > 1) نستبعد −3، فمجموعة الحل {3}، وللتحقق: log₂ 2 + log₂ 4 = 1 + 2 = 3. أما {4} فتنتج من الخطأ الشائع بجمع ما داخل اللوغاريتمين (2x = 8).$q$),
    ('am-009', 0, $q$(f ∘ g)(2) = f(g(2))، فنحسب أولًا g(2) = 4، ثم f(4) = 4 + 3 = 7. أما 25 فهو ناتج (g ∘ f)(2) بعكس ترتيب التركيب.$q$),
    ('am-010', 3, $q$نكتب y = (x − 1)/2 ونبدّل بين x وy: x = (y − 1)/2، ومنه y − 1 = 2x، أي y = 2x + 1؛ إذن f⁻¹(x) = 2x + 1.$q$),
    ('am-011', 0, $q$بما أن 9ˣ = (3ˣ)²، نضع y = 3ˣ فتصبح المعادلة y² − 4y + 3 = 0، أي (y − 1)(y − 3) = 0، ومنه y = 1 أو y = 3. إذن 3ˣ = 1 تعطي x = 0، و3ˣ = 3 تعطي x = 1.$q$),
    ('am-012', 0, $q$في المثلث الثلاثيني الستيني يكون طول الضلع المقابل للزاوية 30° نصف طول الوتر، لذا sin 30° = المقابل ÷ الوتر = 1/2. أما √3/2 فهي قيمة cos 30°.$q$),
    ('am-013', 3, $q$للتحويل من الدرجات إلى الراديان نضرب في π/180: 150 × π/180 = 5π/6.$q$),
    ('am-014', 0, $q$من المتطابقة sin²θ + cos²θ = 1: cos²θ = 1 − 9/25 = 16/25، ومنه cos θ = ±4/5. ولأن جيب التمام سالب في الربع الثاني، فإن cos θ = −4/5.$q$),
    ('am-015', 0, $q$بقانون جيوب التمام: BC² = 5² + 8² − 2 × 5 × 8 × cos 60° = 25 + 64 − 80 × 1/2 = 49، ومنه BC = 7 سم.$q$),
    ('am-016', 1, $q$بالتحليل: (2cos x + 1)(cos x − 1) = 0، فإما cos x = 1 ومنه x = 0، وإما cos x = −1/2 ومنه x = 2π/3 أو x = 4π/3؛ فمجموعة الحل {0, 2π/3, 4π/3}.$q$),
    ('am-017', 3, $q$ميل المستقيم المعطى 2، وحاصل ضرب ميلي مستقيمين متعامدين يساوي −1، لذا الميل المطلوب = −1 ÷ 2 = −1/2.$q$),
    ('am-018', 1, $q$قياس كل زاوية خارجية = 180° − 140° = 40°، ولأن المضلع المنتظم محدب فمجموع قياسات زواياه الخارجية (زاوية عند كل رأس) 360°، إذن عدد الأضلاع = 360° ÷ 40° = 9. وللتحقق: (9 − 2) × 180° ÷ 9 = 1260° ÷ 9 = 140°.$q$),
    ('am-019', 0, $q$بإكمال المربع: (x² − 6x + 9) + (y² + 4y + 4) = 3 + 9 + 4، أي (x − 3)² + (y + 2)² = 16؛ فالمركز (3, −2) ونصف القطر √16 = 4.$q$),
    ('am-020', 1, $q$العمود النازل من المركز على الوتر ينصّفه، فينشأ مثلث قائم وتره نصف القطر 10 وأحد ضلعيه نصف الوتر 8؛ لذا البعد = √(10² − 8²) = √36 = 6 سم.$q$),
    ('am-021', 0, $q$المساحة الجانبية = πrℓ، فـ 3πℓ = 15π ومنه الارتفاع الجانبي ℓ = 5 سم، ثم الارتفاع h = √(5² − 3²) = 4 سم. الحجم = (1/3)πr²h = (1/3)π × 9 × 4 = 12π سم³.$q$),
    ('am-022', 2, $q$التعويض المباشر يعطي الصيغة 0/0، فنحلل البسط: (x − 2)(x + 2)/(x − 2) = x + 2 عندما x ≠ 2، ومنه النهاية = 2 + 2 = 4.$q$),
    ('am-023', 0, $q$بقاعدة مشتقة القوة: مشتقة 3x⁴ هي 4 × 3x³ = 12x³، ومشتقة −5x هي −5، ومشتقة الثابت 2 صفر؛ إذن f′(x) = 12x³ − 5.$q$),
    ('am-024', 3, $q$ميل المماس يساوي قيمة المشتقة عند النقطة: y′ = 3x² − 2، وعند x = 2 يكون الميل 3 × 4 − 2 = 10. أما 4 فهي قيمة y نفسها عند x = 2 وليست الميل.$q$),
    ('am-025', 1, $q$بقاعدة مشتقة الضرب: f′(x) = 2x(x − 2) + (x² + 1) × 1، وعند x = 1: f′(1) = 2 × (−1) + 2 = 0. وللتحقق بالفك: f(x) = x³ − 2x² + x − 2، فـ f′(x) = 3x² − 4x + 1 وf′(1) = 0.$q$),
    ('am-026', 1, $q$الدالة الأصلية للمقدار 3x² + 1 هي x³ + x، وبالتعويض بين الحدين: (2³ + 2) − (0 + 0) = 10.$q$),
    ('am-027', 1, $q$f′(x) = 3x² − 6x − 9 = 3(x − 3)(x + 1)، فالنقطتان الحرجتان x = −1 وx = 3. تتغير إشارة f′ من موجبة إلى سالبة عند x = −1 فتكون عندها قيمة عظمى محلية، أما عند x = 3 فتتغير من سالبة إلى موجبة فتكون صغرى محلية.$q$),
    ('am-028', 0, $q$عدد النواتج الممكنة 6 × 6 = 36، والنواتج التي مجموعها 7 ستة: (1, 6)، (2, 5)، (3, 4)، (4, 3)، (5, 2)، (6, 1)؛ فالاحتمال 6/36 = 1/6.$q$),
    ('am-029', 3, $q$الترتيب غير مهم في اللجنة، فنستخدم التوافيق: ₇C₃ = 7!/(3! × 4!) = (7 × 6 × 5)/(3 × 2 × 1) = 35. أما 210 فهي عدد التباديل ₇P₃ التي تراعي الترتيب.$q$),
    ('am-030', 1, $q$لأن الحادثتين مستقلتان: P(A ∩ B) = 0.4 × 0.5 = 0.2، ومن قاعدة الجمع: P(A ∪ B) = 0.4 + 0.5 − 0.2 = 0.7.$q$),
    ('am-031', 2, $q$الدرجتان 60 و80 تبعدان عن المتوسط انحرافين معياريين (70 ± 2 × 5)، وحسب القاعدة التجريبية تقع نحو 95% من البيانات ضمن انحرافين معياريين من المتوسط.$q$),
    ('am-032', 3, $q$للحصول على لونين مختلفين حالتان: أحمر ثم أزرق واحتماله (4/10) × (6/9) = 4/15، أو أزرق ثم أحمر واحتماله (6/10) × (4/9) = 4/15؛ فالاحتمال الكلي 4/15 + 4/15 = 8/15.$q$),
    ('am-033', 2, $q$الحد النوني للمتتابعة الحسابية aₙ = a₁ + (n − 1)d، إذن a₂₀ = 5 + 19 × 3 = 5 + 57 = 62.$q$),
    ('am-034', 2, $q$أساس المتتابعة r = 6 ÷ 3 = 2، والحد النوني aₙ = a₁ × rⁿ⁻¹، إذن a₈ = 3 × 2⁷ = 3 × 128 = 384.$q$),
    ('am-035', 1, $q$الأساس 4، وعدد الحدود n = (79 − 3)/4 + 1 = 20. المجموع Sₙ = n(a₁ + aₙ)/2 = 20 × (3 + 79)/2 = 20 × 41 = 820.$q$),
    ('am-036', 0, $q$a₆ ÷ a₃ = r³ = 96 ÷ 12 = 8، فالأساس r = 2، والحد الأول a₁ = 12 ÷ 2² = 3. إذن S₅ = a₁(r⁵ − 1)/(r − 1) = 3 × (32 − 1)/1 = 93.$q$),
    ('am-037', 2, $q$محدد المصفوفة من الرتبة 2 × 2 يساوي حاصل ضرب عنصري القطر الرئيس مطروحًا منه حاصل ضرب عنصري القطر الآخر: det(A) = 3 × 4 − 2 × 1 = 12 − 2 = 10.$q$),
    ('am-038', 3, $q$العنصر في الصف الثاني والعمود الأول من AB يساوي ناتج ضرب الصف الثاني من A في العمود الأول من B: (0 × 2) + (3 × 1) = 3. أما 1 فهو العنصر المقابل في BA، لأن ضرب المصفوفات ليس إبداليًا.$q$),
    ('am-039', 2, $q$لا يكون للمصفوفة نظير ضربي إذا كان محددها صفرًا: 6k − 4 × 3 = 0، أي 6k = 12، ومنه k = 2. أما 9/2 فتنتج من الخطأ الشائع بضرب عنصري كل صف بدلًا من عنصري كل قطر (4k = 3 × 6).$q$),
    ('am-040', 2, $q$ضرب المصفوفة في العدد 3 يضرب كلًّا من صفيها في 3، فيُضرب المحدد في 3 مرتين، أي det(3A) = 3² × det(A) = 9 × 5 = 45.$q$)
  ) as v (key, correct_index, explanation)
  join public.questions q on q.key = v.key
on conflict (question_id) do update set
  correct_index = excluded.correct_index,
  explanation   = excluded.explanation
where (k.correct_index, k.explanation) is distinct from (excluded.correct_index, excluded.explanation);

