  ('ap-021', 'achievement', 'physics', 'waves-sound', 1, $q$موجة ترددها 50 Hz وطولها الموجي 4 m. ما سرعة انتشارها؟$q$, null, $q$["0.08 m/s","12.5 m/s","54 m/s","200 m/s"]$q$::jsonb, 60, array[$q$سرعة الموجة$q$, $q$التردد$q$]::text[], (select s.id from public.question_sources s where s.slug = 'jazira-original'), null, null, 'ar', false, true),
