  ('ap-023', 'achievement', 'physics', 'waves-sound', 2, $q$صاح شخص أمام جبل فسمع صدى صوته بعد 2 s. إذا كانت سرعة الصوت في الهواء 340 m/s، فكم يبعد الشخص عن الجبل؟$q$, null, $q$["170 m","340 m","680 m","1360 m"]$q$::jsonb, 75, array[$q$الصدى$q$, $q$سرعة الصوت$q$]::text[], (select s.id from public.question_sources s where s.slug = 'jazira-original'), null, null, 'ar', false, true),
  ('ap-024', 'achievement', 'physics', 'waves-sound', 2, $q$وتر طوله 1.2 m مثبت من طرفيه، يهتز مكوّنًا موجة موقوفة فيها ثلاثة بطون (التوافقية الثالثة). إذا كانت سرعة الموجة في الوتر 48 m/s، فما تردد الاهتزاز؟$q$, null, $q$["20 Hz","40 Hz","60 Hz","120 Hz"]$q$::jsonb, 75, array[$q$الموجات الموقوفة$q$, $q$الأوتار المهتزة$q$]::text[], (select s.id from public.question_sources s where s.slug = 'jazira-original'), null, null, 'ar', false, true),
  ('ap-025', 'achievement', 'physics', 'waves-sound', 3, $q$يقترب مصدر صوت تردده 576 Hz بسرعة 20 m/s من مراقب ساكن. إذا كانت سرعة الصوت في الهواء 340 m/s، فما التردد الذي يسمعه المراقب؟$q$, null, $q$["544 Hz","576 Hz","596 Hz","612 Hz"]$q$::jsonb, 90, array[$q$تأثير دوبلر$q$, $q$التردد$q$]::text[], (select s.id from public.question_sources s where s.slug = 'jazira-original'), null, null, 'ar', false, true),
  ('ap-026', 'achievement', 'physics', 'optics', 1, $q$ما القيمة التقريبية لسرعة الضوء في الفراغ؟$q$, null, $q$["340 m/s","1500 m/s","3 × 10⁵ m/s","3 × 10⁸ m/s"]$q$::jsonb, 60, array[$q$سرعة الضوء$q$]::text[], (select s.id from public.question_sources s where s.slug = 'jazira-original'), null, null, 'ar', false, true),
  ('ap-027', 'achievement', 'physics', 'optics', 1, $q$سقط شعاع ضوئي على مرآة مستوية بحيث يصنع زاوية 30° مع سطح المرآة. ما مقدار زاوية الانعكاس؟$q$, null, $q$["30°","60°","90°","120°"]$q$::jsonb, 60, array[$q$الانعكاس$q$, $q$المرايا المستوية$q$]::text[], (select s.id from public.question_sources s where s.slug = 'jazira-original'), null, null, 'ar', false, true),
  ('ap-028', 'achievement', 'physics', 'optics', 2, $q$وُضع جسم على بعد 30 cm من عدسة محدبة بعدها البؤري 10 cm. على أي بعد من العدسة تتكوّن صورته؟$q$, null, $q$["7.5 cm","15 cm","20 cm","40 cm"]$q$::jsonb, 75, array[$q$العدسات المحدبة$q$, $q$قانون العدسات$q$]::text[], (select s.id from public.question_sources s where s.slug = 'jazira-original'), null, null, 'ar', false, true),
  ('ap-029', 'achievement', 'physics', 'optics', 2, $q$سقط شعاع ضوئي من الهواء بزاوية سقوط 45° على سطح وسط شفاف معامل انكساره √2. ما زاوية الانكسار؟ (اعتبر معامل انكسار الهواء 1)$q$, null, $q$["30°","45°","60°","90°"]$q$::jsonb, 75, array[$q$الانكسار$q$, $q$قانون سنل$q$]::text[], (select s.id from public.question_sources s where s.slug = 'jazira-original'), null, null, 'ar', false, true),
  ('ap-030', 'achievement', 'physics', 'optics', 3, $q$وُضع جسم على بعد 6 cm من عدسة محدبة بعدها البؤري 12 cm. ما صفات الصورة المتكوّنة وما تكبيرها؟$q$, null, $q$["حقيقية مقلوبة، وتكبيرها 2","خيالية معتدلة، وتكبيرها 0.5","حقيقية مقلوبة، وتكبيرها 0.5","خيالية معتدلة، وتكبيرها 2"]$q$::jsonb, 90, array[$q$العدسات المحدبة$q$, $q$التكبير$q$, $q$الصور الخيالية$q$]::text[], (select s.id from public.question_sources s where s.slug = 'jazira-original'), null, null, 'ar', false, true),
  ('ap-031', 'achievement', 'physics', 'thermodynamics', 1, $q$ما درجة الحرارة 27 °C مقيسةً بوحدة الكلفن؟$q$, null, $q$["−246 K","27 K","246 K","300 K"]$q$::jsonb, 60, array[$q$تدريج كلفن$q$, $q$درجة الحرارة$q$]::text[], (select s.id from public.question_sources s where s.slug = 'jazira-original'), null, null, 'ar', false, true),
  ('ap-032', 'achievement', 'physics', 'thermodynamics', 1, $q$ما كمية الحرارة اللازمة لرفع درجة حرارة 2 kg من الماء من 25 °C إلى 40 °C؟ (الحرارة النوعية للماء 4200 J/(kg·°C))$q$, null, $q$["8400 J","63000 J","126000 J","336000 J"]$q$::jsonb, 60, array[$q$الحرارة النوعية$q$, $q$كمية الحرارة$q$]::text[], (select s.id from public.question_sources s where s.slug = 'jazira-original'), null, null, 'ar', false, true),
  ('ap-033', 'achievement', 'physics', 'thermodynamics', 2, $q$خُلط 1 kg من الماء درجة حرارته 80 °C مع 3 kg من الماء درجة حرارته 20 °C في وعاء معزول حراريًا. ما درجة الحرارة النهائية للخليط؟ (أهمل الحرارة التي يكتسبها الوعاء)$q$, null, $q$["35 °C","50 °C","65 °C","100 °C"]$q$::jsonb, 75, array[$q$الاتزان الحراري$q$, $q$انتقال الحرارة$q$]::text[], (select s.id from public.question_sources s where s.slug = 'jazira-original'), null, null, 'ar', false, true),
  ('ap-034', 'achievement', 'physics', 'thermodynamics', 2, $q$امتص غاز محصور كمية من الحرارة مقدارها 500 J، وفي الوقت نفسه بذل المحيط عليه شغلًا مقداره 200 J بضغطه. ما التغير في الطاقة الداخلية للغاز؟$q$, null, $q$["200 J","300 J","500 J","700 J"]$q$::jsonb, 75, array[$q$القانون الأول$q$, $q$الطاقة الداخلية$q$]::text[], (select s.id from public.question_sources s where s.slug = 'jazira-original'), null, null, 'ar', false, true),
  ('ap-035', 'achievement', 'physics', 'thermodynamics', 3, $q$ما كمية الحرارة اللازمة لتحويل 0.5 kg من الجليد عند 0 °C إلى ماء عند 20 °C؟ (الحرارة الكامنة لانصهار الجليد 3.36 × 10⁵ J/kg، والحرارة النوعية للماء 4200 J/(kg·°C))$q$, null, $q$["4.2 × 10⁴ J","1.68 × 10⁵ J","2.1 × 10⁵ J","3.78 × 10⁵ J"]$q$::jsonb, 90, array[$q$الحرارة الكامنة$q$, $q$تغير الحالة$q$]::text[], (select s.id from public.question_sources s where s.slug = 'jazira-original'), null, null, 'ar', false, true),
  ('ap-036', 'achievement', 'physics', 'modern-physics', 1, $q$أي الإشعاعات الكهرومغناطيسية الآتية يحمل الفوتون الواحد منها أكبر طاقة؟$q$, null, $q$["الأشعة السينية","الضوء الأحمر المرئي","الأشعة تحت الحمراء","موجات الراديو"]$q$::jsonb, 60, array[$q$طاقة الفوتون$q$, $q$الطيف الكهرومغناطيسي$q$]::text[], (select s.id from public.question_sources s where s.slug = 'jazira-original'), null, null, 'ar', false, true),
  ('ap-037', 'achievement', 'physics', 'modern-physics', 2, $q$سقط ضوء طاقة فوتونه 5 eV على سطح فلز اقتران الشغل له (دالة الشغل) 2 eV. ما أقصى طاقة حركية للإلكترونات المتحررة من السطح؟$q$, null, $q$["2.5 eV","3 eV","7 eV","10 eV"]$q$::jsonb, 75, array[$q$التأثير الكهروضوئي$q$, $q$اقتران الشغل$q$]::text[], (select s.id from public.question_sources s where s.slug = 'jazira-original'), null, null, 'ar', false, true),
  ('ap-038', 'achievement', 'physics', 'modern-physics', 2, $q$عينة من نظير مشع كتلتها 80 g، وعمر النصف له 5 أيام. ما كتلة الجزء المتبقي دون تحلل من العينة بعد 15 يومًا؟$q$, null, $q$["10 g","20 g","26.7 g","40 g"]$q$::jsonb, 75, array[$q$عمر النصف$q$, $q$النشاط الإشعاعي$q$]::text[], (select s.id from public.question_sources s where s.slug = 'jazira-original'), null, null, 'ar', false, true),
  ('ap-039', 'achievement', 'physics', 'modern-physics', 2, $q$تحللت نواة يورانيوم عددها الكتلي 238 وعددها الذري 92 بإطلاق جسيم ألفا. ما العدد الكتلي والعدد الذري للنواة الناتجة؟$q$, null, $q$["العدد الكتلي 238 والعدد الذري 90","العدد الكتلي 234 والعدد الذري 94","العدد الكتلي 236 والعدد الذري 90","العدد الكتلي 234 والعدد الذري 90"]$q$::jsonb, 75, array[$q$تحلل ألفا$q$, $q$التفاعلات النووية$q$]::text[], (select s.id from public.question_sources s where s.slug = 'jazira-original'), null, null, 'ar', false, true),
  ('ap-040', 'achievement', 'physics', 'modern-physics', 3, $q$تُعطى طاقة المستوى n في ذرة الهيدروجين بالعلاقة E = (−13.6 ÷ n²) eV. ما طاقة الفوتون المنبعث عند انتقال الإلكترون من المستوى n = 4 إلى المستوى n = 2؟$q$, null, $q$["0.85 eV","2.55 eV","3.4 eV","4.25 eV"]$q$::jsonb, 90, array[$q$نموذج بور$q$, $q$مستويات الطاقة$q$]::text[], (select s.id from public.question_sources s where s.slug = 'jazira-original'), null, null, 'ar', false, true)
on conflict (key) do update set
  exam = excluded.exam,
  section = excluded.section,
  topic = excluded.topic,
  difficulty = excluded.difficulty,
  stem = excluded.stem,
  passage = excluded.passage,
  choices = excluded.choices,
  time_limit_seconds = excluded.time_limit_seconds,
  tags = excluded.tags,
  source_id = excluded.source_id,
  source_ref = excluded.source_ref,
  year = excluded.year,
  language = excluded.language,
  is_premium = excluded.is_premium,
  is_active = excluded.is_active
where (q.exam, q.section, q.topic, q.difficulty, q.stem, q.passage, q.choices, q.time_limit_seconds, q.tags, q.source_id, q.source_ref, q.year, q.language, q.is_premium, q.is_active)
  is distinct from (excluded.exam, excluded.section, excluded.topic, excluded.difficulty, excluded.stem, excluded.passage, excluded.choices, excluded.time_limit_seconds, excluded.tags, excluded.source_id, excluded.source_ref, excluded.year, excluded.language, excluded.is_premium, excluded.is_active);

insert into public.question_keys as k (question_id, correct_index, explanation)
select q.id, v.correct_index, v.explanation
  from (values
    ('ap-001', 1, $q$التسارع = التغير في السرعة ÷ الزمن = (20 − 0) ÷ 5 = 4 m/s².$q$),
    ('ap-002', 2, $q$الإزاحة كمية متجهة تصل نقطة البداية بنقطة النهاية، والحركتان متعامدتان، فمقدارها = √(30² + 40²) = √2500 = 50 m. أما 70 m فهي المسافة المقطوعة لا الإزاحة.$q$),
    ('ap-003', 2, $q$من معادلة الحركة d = ½gt² = ½ × 9.8 × 3² = 4.9 × 9 = 44.1 m. والقيمة 88.2 m تنتج عن إهمال المعامل ½، أما 29.4 فهي مقدار السرعة بوحدة m/s بعد 3 s لا المسافة.$q$),
    ('ap-004', 0, $q$باستخدام v² = v₀² − 2ad مع v = 0 نجد d = v₀² ÷ (2a) = 400 ÷ 8 = 50 m. وإهمال العدد 2 في المقام يعطي 100 m خطأً.$q$),
    ('ap-005', 1, $q$الحركة الرأسية سقوط حر من السكون: 78.4 = ½ × 9.8 × t²، إذن t² = 16 وt = 4 s. والسرعة الأفقية ثابتة لانعدام القوة الأفقية، فالمسافة الأفقية = 15 × 4 = 60 m.$q$),
    ('ap-006', 3, $q$تُقاس القوة بالنيوتن، وهو القوة التي تُكسب جسمًا كتلته 1 kg تسارعًا مقداره 1 m/s²، أي N = kg·m/s². أما الجول فوحدة الشغل والطاقة، والواط وحدة القدرة، والباسكال وحدة الضغط.$q$),
    ('ap-007', 0, $q$القوة المحصلة = 20 − 8 = 12 N باتجاه القوة الأكبر (الشرق)، ومن قانون نيوتن الثاني a = F ÷ m = 12 ÷ 4 = 3 m/s² نحو الشرق.$q$),
    ('ap-008', 0, $q$قوتا الفعل وردّ الفعل متساويتان مقدارًا ومتعاكستان اتجاهًا ومن النوع نفسه، وتؤثران في جسمين مختلفين؛ فالأرض تجذب الكتاب والكتاب يجذب الأرض. أما دفع الطاولة للكتاب إلى أعلى فيؤثر في الكتاب نفسه ويتزن مع وزنه، فليس ردَّ فعلٍ له. وأما قوة ضغط الكتاب على سطح الطاولة فهي ردُّ فعلٍ لقوة دفع الطاولة للكتاب (القوة العمودية) لا لوزنه، وإن ساوت الوزن مقدارًا في هذه الحالة؛ فهي قوة تلامس تؤثر في الطاولة، بينما الوزن قوة تجاذب بين الكتاب والأرض. ولا تنشأ هنا قوة احتكاك أصلًا لعدم وجود قوة أفقية تحاول تحريك الكتاب.$q$),
    ('ap-009', 1, $q$السرعة ثابتة، فالقوة المحصلة صفر، أي أن قوة السحب تساوي قوة الاحتكاك الحركي: F = μmg = 0.4 × 5 × 9.8 = 19.6 N. والقيمة 49 N هي وزن الصندوق، و2 N تنتج عن إهمال g.$q$),
    ('ap-010', 0, $q$يتحرك الصندوقان بالتسارع نفسه: a = 30 ÷ (4 + 2) = 5 m/s². والقوة الأفقية الوحيدة المؤثرة في الصندوق الثاني هي دفع الأول له، فمقدارها = 2 × 5 = 10 N. أما 20 N فهي القوة المحصلة المؤثرة في الصندوق الأول (4 × 5)، و30 N هي القوة الخارجية كاملة.$q$),
    ('ap-011', 2, $q$الطاقة الحركية KE = ½mv² = ½ × 2 × 3² = 9 J. والقيمة 18 J تنتج عن إهمال ½، و6 J عن عدم تربيع السرعة.$q$),
    ('ap-012', 1, $q$الشغل W = Fd cos θ = 50 × 4 × cos 60° = 200 × 0.5 = 100 J. واستخدام sin بدلًا من cos يعطي 100√3 J، وإهمال الزاوية يعطي 200 J.$q$),
    ('ap-013', 2, $q$الشغل المبذول يساوي الزيادة في طاقة الوضع: W = mgh = 100 × 9.8 × 6 = 5880 J، والقدرة P = W ÷ t = 5880 ÷ 20 = 294 W.$q$),
    ('ap-014', 3, $q$طاقة الوضع الجاذبية PE = mgh = 3 × 9.8 × 5 = 147 J. أما 15 J فتنتج عن إهمال g، و73.5 J عن ضرب الناتج في ½ خطأً، و29.4 هي مقدار وزن الجسم بوحدة N لا طاقته.$q$),
    ('ap-015', 2, $q$على المسار الأملس تتحول طاقة الوضع mgh كلها إلى طاقة حركية، ثم يستنفدها شغل الاحتكاك على السطح الخشن: mgh = μmgd. إذن d = h ÷ μ = 10 ÷ 0.5 = 20 m، ولا تعتمد النتيجة على الكتلة ولا على قيمة g لأنهما تُختصران من طرفي المعادلة.$q$),
    ('ap-016', 0, $q$من قانون أوم: I = V ÷ R = 12 ÷ 4 = 3 A.$q$),
    ('ap-017', 2, $q$المقاومة المكافئة على التوالي = 2 + 4 + 6 = 12 Ω، فالتيار في الدائرة I = 24 ÷ 12 = 2 A، وهو نفسه في كل مقاومة؛ إذن فرق الجهد V = IR = 2 × 6 = 12 V.$q$),
    ('ap-018', 1, $q$على التوازي: 1/R = 1/3 + 1/6 = 2/6 + 1/6 = 1/2، إذن R = 2 Ω، وهي أصغر من أصغر المقاومتين كما هو متوقع. والقيمة 0.5 Ω تنتج عن نسيان قلب الكسر، و9 Ω هي المكافئة على التوالي.$q$),
    ('ap-019', 2, $q$الطاقة = القدرة × الزمن، والقدرة 2000 W = 2 kW، فالطاقة = 2 × 3 = 6 kWh. أما 6000 فتنتج عن عدم تحويل الواط إلى كيلوواط.$q$),
    ('ap-020', 3, $q$من قانون كولوم F = kq₁q₂ ÷ r²: مضاعفة الشحنتين تضرب البسط في 2 × 2 = 4، وتنصيف المسافة يقسم المقام على 4 فيضرب القوة في 4 أيضًا؛ إذن القوة الجديدة = 4 × 4 × F = 16F.$q$),
    ('ap-021', 3, $q$سرعة الموجة تساوي حاصل ضرب ترددها في طولها الموجي: v = fλ = 50 × 4 = 200 m/s.$q$),
    ('ap-022', 0, $q$الصوت موجة ميكانيكية طولية تنتقل عبر تضاغطات جزيئات الوسط وتخلخلاتها، وفي الفراغ لا توجد جزيئات تهتز فلا ينتقل الصوت. أما الضوء فموجة كهرومغناطيسية تنتقل في الفراغ، ولذلك يُرى وميض الانفجار دون سماع صوته.$q$),
    ('ap-023', 1, $q$الزمن 2 s هو زمن ذهاب الصوت إلى الجبل وعودته، فالمسافة التي قطعها الصوت = 340 × 2 = 680 m، وبُعد الشخص عن الجبل نصفها، أي 340 m.$q$),
    ('ap-024', 2, $q$في الوتر المثبت من طرفيه يقع بين كل عقدتين متتاليتين بطن واحد، والمسافة بين العقدتين نصف طول موجي؛ فالبطون الثلاثة تعني أن طول الوتر ثلاثة أنصاف طول موجي: 3 × λ/2 = 1.2 m، إذن λ = 0.8 m، والتردد f = v ÷ λ = 48 ÷ 0.8 = 60 Hz. أما 20 Hz فهو التردد الأساسي (التوافقية الأولى) لهذا الوتر.$q$),
    ('ap-025', 3, $q$عند اقتراب المصدر تتقارب مقدمات الموجات فيزداد التردد المسموع: f = f₀ × v ÷ (v − u)، حيث u سرعة المصدر، أي f = 576 × 340 ÷ 320 = 612 Hz. أما 544 Hz فهو التردد المسموع لو كان المصدر مبتعدًا (المقام v + u = 360).$q$),
    ('ap-026', 3, $q$سرعة الضوء في الفراغ c ≈ 3 × 10⁸ m/s، أي نحو 300000 km/s. والقيمة 3 × 10⁵ m/s تنتج عن الخلط بين km/s وm/s، أما 340 m/s و1500 m/s فهما سرعتا الصوت تقريبًا في الهواء والماء.$q$),
    ('ap-027', 1, $q$تُقاس زاويتا السقوط والانعكاس من العمود المقام على سطح المرآة، فزاوية السقوط = 90° − 30° = 60°، وزاوية الانعكاس تساويها: 60°. أما 120° فهي الزاوية بين الشعاعين الساقط والمنعكس.$q$),
    ('ap-028', 1, $q$من قانون العدسات: 1/f = 1/(بعد الجسم) + 1/(بعد الصورة)، إذن 1/(بعد الصورة) = 1/10 − 1/30 = 3/30 − 1/30 = 2/30، فبعد الصورة = 15 cm، وهي صورة حقيقية مقلوبة على الجانب الآخر من العدسة.$q$),
    ('ap-029', 0, $q$من قانون سنل: 1 × sin 45° = √2 × sin r، أي √2/2 = √2 sin r، إذن sin r = 1/2 وr = 30°. وينكسر الشعاع مقتربًا من العمود المقام لأنه انتقل إلى وسط معامل انكساره أكبر.$q$),
    ('ap-030', 3, $q$1/(بعد الصورة) = 1/12 − 1/6 = −1/12، إذن بعد الصورة = −12 cm، والإشارة السالبة تعني أن الصورة خيالية معتدلة في جهة الجسم نفسها. والتكبير = −(بعد الصورة) ÷ (بعد الجسم) = 12 ÷ 6 = 2، فالجسم داخل البعد البؤري كما في العدسة المكبرة.$q$),
    ('ap-031', 3, $q$درجة الحرارة بالكلفن = درجة الحرارة السيليزية + 273 (بالتقريب؛ والقيمة الدقيقة 273.15) = 27 + 273 = 300 K. أما −246 K فتنتج عن طرح 273 من 27 بدلًا من الجمع، وهي قيمة مستحيلة لأن درجة الحرارة المطلقة لا تكون سالبة، و246 K تنتج عن طرح 27 من 273، و27 K عن إهمال التحويل.$q$),
    ('ap-032', 2, $q$Q = mcΔT = 2 × 4200 × (40 − 25) = 2 × 4200 × 15 = 126000 J. والقيمة 336000 J تنتج عن استخدام درجة الحرارة النهائية 40 بدلًا من التغير فيها، و63000 J عن إهمال الكتلة، و8400 J عن إهمال التغير في درجة الحرارة.$q$),
    ('ap-033', 0, $q$الحرارة التي يفقدها الماء الساخن = الحرارة التي يكتسبها الماء البارد: 1 × c × (80 − T) = 3 × c × (T − 20)، إذن 80 − T = 3T − 60، فـ 4T = 140 وT = 35 °C. أما 50 °C فهي المتوسط البسيط الذي يهمل اختلاف الكتلتين.$q$),
    ('ap-034', 3, $q$وفق القانون الأول للديناميكا الحرارية ΔU = Q − W، حيث W الشغل الذي يبذله الغاز. والغاز هنا بُذل عليه الشغل، فـ W = −200 J، وعليه ΔU = 500 − (−200) = 700 J؛ أي أن الحرارة الممتصة والشغل المبذول عليه كليهما زادا طاقته الداخلية.$q$),
    ('ap-035', 2, $q$تُحسب الحرارة على مرحلتين: الانصهار عند 0 °C: Q₁ = mL = 0.5 × 3.36 × 10⁵ = 1.68 × 10⁵ J، ثم تسخين الماء الناتج: Q₂ = mcΔT = 0.5 × 4200 × 20 = 4.2 × 10⁴ J. المجموع Q = 1.68 × 10⁵ + 0.42 × 10⁵ = 2.1 × 10⁵ J.$q$),
    ('ap-036', 0, $q$طاقة الفوتون E = hf تتناسب طرديًا مع التردد، والأشعة السينية أعلى هذه الإشعاعات ترددًا وأقصرها طولًا موجيًا، فطاقة فوتونها هي الأكبر، بينما فوتونات موجات الراديو أقلها طاقة.$q$),
    ('ap-037', 1, $q$من معادلة أينشتاين للتأثير الكهروضوئي: الطاقة الحركية القصوى = hf − اقتران الشغل = 5 − 2 = 3 eV؛ إذ يُستهلك من طاقة الفوتون ما يساوي اقتران الشغل لتحرير الإلكترون، ويبقى الباقي طاقة حركية.$q$),
    ('ap-038', 0, $q$المدة 15 يومًا تساوي 3 أعمار نصف (15 ÷ 5 = 3)، وفي كل عمر نصف تتناقص الكمية المتبقية إلى النصف: 80 ثم 40 ثم 20 ثم 10 g.$q$),
    ('ap-039', 3, $q$جسيم ألفا نواة هيليوم عددها الكتلي 4 وعددها الذري 2، فعند إطلاقه ينقص العدد الكتلي 4 والعدد الذري 2: 238 − 4 = 234، و92 − 2 = 90، وهي نواة الثوريوم.$q$),
    ('ap-040', 1, $q$طاقة المستوى الرابع E₄ = (−13.6 ÷ 4²) eV = −0.85 eV، وطاقة المستوى الثاني E₂ = (−13.6 ÷ 2²) eV = −3.4 eV، وطاقة الفوتون المنبعث تساوي الفرق بينهما: −0.85 − (−3.4) = 2.55 eV. أما 4.25 eV فتنتج عن جمع المقدارين بدلًا من طرحهما.$q$)
  ) as v (key, correct_index, explanation)
  join public.questions q on q.key = v.key
on conflict (question_id) do update set
  correct_index = excluded.correct_index,
  explanation   = excluded.explanation
where (k.correct_index, k.explanation) is distinct from (excluded.correct_index, excluded.explanation);

