  ('ac-028', 'achievement', 'chemistry', 'acids-bases', 2, $q$في التفاعل NH₃ + H₂O ⇌ NH₄⁺ + OH⁻، ما الحمض المرافق للقاعدة NH₃؟$q$, null, $q$["H₂O","OH⁻","NH₂⁻","NH₄⁺"]$q$::jsonb, 75, array[$q$الأزواج المترافقة$q$, $q$مفهوم برونستد–لوري$q$]::text[], (select s.id from public.question_sources s where s.slug = 'jazira-original'), null, null, 'ar', false, true),
  ('ac-029', 'achievement', 'chemistry', 'acids-bases', 2, $q$ما الرقم الهيدروجيني pH لمحلول هيدروكسيد الصوديوم NaOH تركيزه 0.01 M عند 25 °C؟$q$, null, $q$["1","2","12","13"]$q$::jsonb, 75, array[$q$الرقم الهيدروجيني$q$, $q$القواعد القوية$q$]::text[], (select s.id from public.question_sources s where s.slug = 'jazira-original'), null, null, 'ar', false, true),
  ('ac-030', 'achievement', 'chemistry', 'acids-bases', 3, $q$لزم 25.0 mL من محلول هيدروكسيد الصوديوم NaOH تركيزه 0.20 M لمعايرة 20.0 mL من محلول حمض الكبريتيك H₂SO₄ حتى نقطة التكافؤ. ما تركيز الحمض؟$q$, null, $q$["0.0625 M","0.125 M","0.16 M","0.25 M"]$q$::jsonb, 90, array[$q$المعايرة$q$, $q$التعادل$q$]::text[], (select s.id from public.question_sources s where s.slug = 'jazira-original'), null, null, 'ar', false, true),
  ('ac-031', 'achievement', 'chemistry', 'thermochemistry', 1, $q$يتفاعل أكسيد الكالسيوم مع الماء وفق المعادلة الكيميائية الحرارية: CaO(s) + H₂O(l) → Ca(OH)₂(s)، ΔH = −65 kJ. أي العبارات الآتية تصف هذا التفاعل وصفًا صحيحًا؟$q$, null, $q$["ماص للحرارة؛ لأن النواتج أقل طاقة من المتفاعلات","ماص للحرارة؛ لأن الطاقة تُمتص من المحيط","طارد للحرارة؛ لأن الطاقة تنطلق إلى المحيط","طارد للحرارة؛ لأن النواتج أعلى طاقة من المتفاعلات"]$q$::jsonb, 60, array[$q$المحتوى الحراري$q$, $q$التفاعل الطارد للحرارة$q$]::text[], (select s.id from public.question_sources s where s.slug = 'jazira-original'), null, null, 'ar', false, true),
  ('ac-032', 'achievement', 'chemistry', 'thermochemistry', 1, $q$امتصت عينة من فلز كتلتها 20 g كمية من الحرارة مقدارها 180 J، فارتفعت درجة حرارتها من 25 °C إلى 35 °C. ما الحرارة النوعية للفلز؟$q$, null, $q$["0.26 J/(g·°C)","0.90 J/(g·°C)","1.11 J/(g·°C)","9.00 J/(g·°C)"]$q$::jsonb, 60, array[$q$الحرارة النوعية$q$, $q$كمية الحرارة$q$]::text[], (select s.id from public.question_sources s where s.slug = 'jazira-original'), null, null, 'ar', false, true),
  ('ac-033', 'achievement', 'chemistry', 'thermochemistry', 2, $q$إذا علمت أن ΔH للتفاعل C(s) + O₂(g) → CO₂(g) يساوي −394 kJ، وأن ΔH للتفاعل CO(g) + ½O₂(g) → CO₂(g) يساوي −283 kJ، فما ΔH للتفاعل C(s) + ½O₂(g) → CO(g)؟$q$, null, $q$["−111 kJ","+111 kJ","−677 kJ","+677 kJ"]$q$::jsonb, 90, array[$q$قانون هس$q$, $q$المحتوى الحراري$q$]::text[], (select s.id from public.question_sources s where s.slug = 'jazira-original'), null, null, 'ar', false, true),
  ('ac-034', 'achievement', 'chemistry', 'thermochemistry', 2, $q$احسب ΔH للتفاعل CH₄(g) + 2O₂(g) → CO₂(g) + 2H₂O(l)، علمًا بأن حرارات التكوين القياسية بوحدة kJ/mol هي: CH₄ = −75، CO₂ = −394، H₂O(l) = −286.$q$, null, $q$["−891 kJ","−680 kJ","−605 kJ","+891 kJ"]$q$::jsonb, 90, array[$q$حرارة التكوين القياسية$q$, $q$المحتوى الحراري$q$]::text[], (select s.id from public.question_sources s where s.slug = 'jazira-original'), null, null, 'ar', false, true),
  ('ac-035', 'achievement', 'chemistry', 'thermochemistry', 3, $q$تفاعل فيه ΔH = +40 kJ، وΔS = +125 J/K. إذا افترضنا ثبات القيمتين، فما درجة الحرارة التي يصبح التفاعل تلقائيًا عند تجاوزها؟$q$, null, $q$["0.32 K","320 K","593 K","5000 K"]$q$::jsonb, 90, array[$q$طاقة جبس الحرة$q$, $q$التلقائية$q$]::text[], (select s.id from public.question_sources s where s.slug = 'jazira-original'), null, null, 'ar', false, true),
  ('ac-036', 'achievement', 'chemistry', 'organic', 1, $q$ما الصيغة الجزيئية للألكين غير الحلقي الذي يحتوي جزيئه على 4 ذرات كربون ورابطة ثنائية واحدة؟$q$, null, $q$["C₄H₁₀","C₄H₆","C₄H₈","C₄H₄"]$q$::jsonb, 60, array[$q$الألكينات$q$, $q$الصيغة العامة$q$]::text[], (select s.id from public.question_sources s where s.slug = 'jazira-original'), null, null, 'ar', false, true),
  ('ac-037', 'achievement', 'chemistry', 'organic', 1, $q$إلى أي عائلة من المركبات العضوية ينتمي المركب CH₃CH₂OH؟$q$, null, $q$["الإيثرات","الألدهيدات","الأحماض الكربوكسيلية","الكحولات"]$q$::jsonb, 60, array[$q$المجموعات الوظيفية$q$, $q$الكحولات$q$]::text[], (select s.id from public.question_sources s where s.slug = 'jazira-original'), null, null, 'ar', false, true),
  ('ac-038', 'achievement', 'chemistry', 'organic', 2, $q$ما الاسم النظامي (IUPAC) للمركب CH₃–CH(CH₃)–CH₂–CH₃؟$q$, null, $q$["2-ميثيل بيوتان","3-ميثيل بيوتان","2-إيثيل بروبان","2-ميثيل بنتان"]$q$::jsonb, 75, array[$q$تسمية المركبات العضوية$q$, $q$الألكانات$q$]::text[], (select s.id from public.question_sources s where s.slug = 'jazira-original'), null, null, 'ar', false, true),
  ('ac-039', 'achievement', 'chemistry', 'organic', 2, $q$ما نوع التفاعل الآتي: CH₂=CH₂ + Br₂ → CH₂Br–CH₂Br؟$q$, null, $q$["استبدال","إضافة","حذف","تكثف"]$q$::jsonb, 75, array[$q$تفاعلات الإضافة$q$, $q$الألكينات$q$]::text[], (select s.id from public.question_sources s where s.slug = 'jazira-original'), null, null, 'ar', false, true),
  ('ac-040', 'achievement', 'chemistry', 'organic', 3, $q$ما الاسم النظامي للإستر الذي صيغته CH₃CH₂COOCH₃؟$q$, null, $q$["بروبانوات الميثيل","إيثانوات الإيثيل","ميثانوات البروبيل","بيوتانوات الميثيل"]$q$::jsonb, 90, array[$q$الإسترات$q$, $q$تسمية المركبات العضوية$q$]::text[], (select s.id from public.question_sources s where s.slug = 'jazira-original'), null, null, 'ar', false, true)
