insert into public.question_keys as k (question_id, correct_index, explanation)
select q.id, v.correct_index, v.explanation
  from (values
    ('ac-001', 1, $q$العدد الذري هو عدد البروتونات في نواة الذرة، ونواة ذرة الكربون تحتوي على 6 بروتونات؛ فعدده الذري 6. أما 12 فهو العدد الكتلي لنظيره الأكثر شيوعًا، و4 هو عدد إلكترونات التكافؤ في ذرته، و8 هو العدد الذري للأكسجين.$q$),
    ('ac-002', 3, $q$العدد الكتلي هو مجموع البروتونات والنيوترونات في النواة، وعدد البروتونات يساوي العدد الذري؛ لذا العدد الكتلي = 17 + 20 = 37.$q$),
    ('ac-003', 0, $q$تُملأ مستويات الطاقة الثانوية وفق مبدأ أوفباو بالترتيب 1s ثم 2s ثم 2p ثم 3s ثم 3p، فتضم المستويات الثانوية 1s و2s و2p و3s معًا 2 + 2 + 6 + 2 = 12 إلكترونًا، وتبقى 16 − 12 = 4 إلكترونات في 3p. أما التوزيع المنتهي بـ 3p⁶ فيضم 18 إلكترونًا، والتوزيعان الآخران يخالفان ترتيب الملء.$q$),
    ('ac-004', 2, $q$متوسط الكتلة الذرية متوسط موزون بنسب الوفرة: (10 × 0.20) + (11 × 0.80) = 2.0 + 8.8 = 10.8 amu. أما 10.5 فمتوسط بسيط يهمل الوفرة، و10.2 تنتج من عكس النسبتين.$q$),
    ('ac-005', 2, $q$توزيع ذرة الحديد [Ar] 4s² 3d⁶، وعند تكوين الأيون تُفقد إلكترونات 4s أولًا ثم إلكترون واحد من 3d، فيصبح توزيع Fe³⁺ هو [Ar] 3d⁵. ووفق قاعدة هوند تشغل الإلكترونات الخمسة أفلاك 3d الخمسة منفردةً؛ فعدد الإلكترونات المنفردة 5.$q$),
    ('ac-006', 3, $q$عدد إلكترونات التكافؤ في المستوى الخارجي 2 + 5 = 7، وهذه سمة عناصر المجموعة 17 (الهالوجينات)، والعنصر هو الكلور في الدورة الثالثة.$q$),
    ('ac-007', 0, $q$تقل الكهروسالبية في المجموعة الواحدة من أعلى إلى أسفل؛ لأن زيادة عدد مستويات الطاقة تُبعد إلكترونات الرابطة عن النواة فيضعف جذبها لها. والفلور أول عناصر المجموعة 17، فهو الأعلى كهروسالبية بينها.$q$),
    ('ac-008', 2, $q$رقم الدورة يدل على رقم مستوى الطاقة الخارجي (n = 4)، وعناصر المجموعة 2 لها إلكترونا تكافؤ في المستوى s؛ فالتوزيع [Ar] 4s² وهو الكالسيوم. أما [Ne] 3s² فللمغنيسيوم في الدورة الثالثة، و[Ar] 4s¹ للبوتاسيوم في المجموعة 1، و[Ar] 4s² 3d² للتيتانيوم في المجموعة 4.$q$),
    ('ac-009', 1, $q$تقفز طاقة التأين قفزة كبيرة بين الثانية (1451) والثالثة (7733)، أي إن الإلكترون الثالث يُنزع من مستوى داخلي مكتمل. إذن للعنصر إلكترونا تكافؤ فقط، فهو من المجموعة 2 (المغنيسيوم).$q$),
    ('ac-010', 3, $q$لكل أيون منها 10 إلكترونات، لكن عدد البروتونات يزداد: O (8) ثم F (9) ثم Na (11) ثم Mg (12). وكلما زادت الشحنة النووية جذبت النواة الإلكترونات العشرة بقوة أكبر فصغر نصف القطر؛ لذا Mg²⁺ أصغرها وO²⁻ أكبرها.$q$),
    ('ac-011', 0, $q$للأكسجين 6 إلكترونات تكافؤ، يشارك باثنين منها في رابطتين تساهميتين مع ذرتي الهيدروجين، فتبقى 4 إلكترونات غير رابطة تشكّل زوجين؛ وتنافر هذين الزوجين مع الزوجين الرابطين سبب الشكل المنحني للجزيء. أما 4 فهو عدد الإلكترونات غير الرابطة لا عدد أزواجها، و3 تنتج من عدّ إلكترونات التكافؤ الستة كلها أزواجًا غير رابطة، و6 هو عدد إلكترونات تكافؤ الأكسجين.$q$),
    ('ac-012', 3, $q$مجموع شحنات المركب الأيوني يساوي صفرًا: 2 × (+3) + 3 × (−2) = 0، فأبسط نسبة بين الأيونات 2 : 3، والصيغة Al₂O₃ (أكسيد الألومنيوم). أما Al₃O₂ فتنتج من تبديل الأرقام السفلية خطأً.$q$),
    ('ac-013', 2, $q$لذرة النيتروجين المركزية ثلاثة أزواج رابطة وزوج واحد غير رابط، فتتوزع الأزواج الأربعة توزيعًا رباعي الأوجه. لكن الشكل الجزيئي يصف مواقع الذرات فقط، فيكون هرمًا ثلاثيًا بزاوية رابطة نحو 107°.$q$),
    ('ac-014', 1, $q$روابط C=O في CO₂ قطبية، لكن الجزيء خطي تقع فيه ذرتا الأكسجين على جانبي ذرة الكربون بزاوية 180°، فتلغي قطبيتا الرابطتين إحداهما الأخرى. أما H₂O المنحني وNH₃ الهرمي فلا تتلاشى فيهما القطبية، وHCl جزيء ثنائي الذرة قطبي.$q$),
    ('ac-015', 3, $q$كل رابطة أحادية σ، وكل رابطة ثنائية σ + π، وكل رابطة ثلاثية σ + 2π. في الجزيء 3 روابط C–H ورابطة C–C أحادية (4σ)، ورابطة C=C (1σ + 1π)، ورابطة C≡N (1σ + 2π)؛ فالمجموع 6σ و3π.$q$),
    ('ac-016', 3, $q$الكتلة المولية مجموع كتل ذرات الصيغة مضروبة في أعدادها: 40 + 12 + (3 × 16) = 100 g/mol. والقيم الأخرى تنتج من إهمال ذرات الأكسجين الثلاث كلها أو بعضها.$q$),
    ('ac-017', 0, $q$الكتلة المولية للماء = 2 × 1 + 16 = 18 g/mol، فعدد المولات = 9 ÷ 18 = 0.5 mol. وعدد الجزيئات = 0.5 × 6.02 × 10²³ = 3.01 × 10²³ جزيء.$q$),
    ('ac-018', 2, $q$عدد مولات H₂ = 6 ÷ 2 = 3 mol، ومن المعادلة كل 3 mol من H₂ تنتج 2 mol من NH₃. والكتلة المولية للأمونيا = 14 + 3 × 1 = 17 g/mol؛ فالكتلة الناتجة = 2 × 17 = 34 g. أما 4 g فتنتج من تطبيق النسبة المولية على الكتل مباشرة.$q$),
    ('ac-019', 2, $q$في عينة كتلتها 100 g: مولات C = 40 ÷ 12 ≈ 3.33، ومولات H = 6.7 ÷ 1 = 6.7، ومولات O = 53.3 ÷ 16 ≈ 3.33. وبالقسمة على أصغرها (3.33) تكون النسبة 1 : 2 : 1، فالصيغة الأولية CH₂O.$q$),
    ('ac-020', 1, $q$مولات H₂ = 4 ÷ 2 = 2 mol، ومولات O₂ = 16 ÷ 32 = 0.5 mol. يحتاج 2 mol من H₂ إلى 1 mol من O₂ ولا يتوافر إلا 0.5 mol، فالأكسجين هو المادة المحددة للتفاعل. ينتج عنه 2 × 0.5 = 1 mol من الماء، أي 18 g، ويبقى جزء من الهيدروجين دون تفاعل؛ لذا لا تصح القيمة 20 g.$q$),
    ('ac-021', 3, $q$المولارية = عدد مولات المذاب ÷ حجم المحلول باللتر = 0.5 ÷ 0.250 = 2 M. أما 0.002 M فتنتج من القسمة على الحجم بالمليلتر دون تحويله إلى لتر.$q$),
    ('ac-022', 0, $q$عدد مولات المذاب لا يتغير بالتخفيف: M₁V₁ = M₂V₂، إذن V₁ = (1.5 × 300) ÷ 6 = 75 mL، ثم يُضاف الماء حتى يصبح الحجم 300 mL. أما 225 mL فهي حجم الماء المضاف لا حجم المحلول المركز.$q$),
    ('ac-023', 3, $q$الكتلة المولية لـ NaCl = 23 + 35.5 = 58.5 g/mol، فعدد المولات = 11.7 ÷ 58.5 = 0.2 mol. والمولالية = مولات المذاب ÷ كتلة المذيب بالكيلوجرام = 0.2 ÷ 0.500 = 0.4 m.$q$),
    ('ac-024', 2, $q$وفق قانون هنري تتناسب ذائبية الغاز طرديًا مع ضغطه فوق السائل: S₁ ÷ P₁ = S₂ ÷ P₂، إذن S₂ = 0.8 × 3 ÷ 1 = 2.4 g/L. أما 0.27 g/L فتنتج من عكس التناسب.$q$),
    ('ac-025', 0, $q$المولالية = 0.1 ÷ 0.5 = 0.2 m، ويتفكك CaCl₂ إلى 3 أيونات (Ca²⁺ وأيونَي Cl⁻)، فمولالية الجسيمات = 3 × 0.2 = 0.6 m. والانخفاض في درجة التجمد ΔTf = Kf × m = 1.86 × 0.6 ≈ 1.12 °C، فتصبح درجة التجمد −1.12 °C. أما −0.37 °C فتنتج من إهمال التفكك.$q$),
    ('ac-026', 1, $q$يعرّف برونستد–لوري الحمض بأنه مادة مانحة لأيون الهيدروجين (البروتون)، والقاعدة بأنها مستقبلة له. أما منح زوج الإلكترونات فتعريف قاعدة لويس، وإنتاج OH⁻ في الماء تعريف قاعدة أرهينيوس.$q$),
    ('ac-027', 1, $q$0.001 M = 1 × 10⁻³ M، وpH = −log[H⁺] = −log(10⁻³) = 3. أما 11 فهي قيمة pOH للمحلول نفسه عند 25 °C (14 − 3)، و2 تنتج من عدّ الأصفار بعد الفاصلة العشرية فقط.$q$),
    ('ac-028', 3, $q$تستقبل NH₃ بروتونًا من الماء فتتحول إلى NH₄⁺، والحمض المرافق هو ما تتحول إليه القاعدة بعد اكتسابها H⁺؛ فهو NH₄⁺. أما OH⁻ فهو القاعدة المرافقة للحمض H₂O، وNH₂⁻ ينتج من فقد بروتون لا من اكتسابه.$q$),
    ('ac-029', 2, $q$NaOH قاعدة قوية تتفكك كليًا، فيكون [OH⁻] = 0.01 M = 10⁻² M، ومنه pOH = 2، وpH = 14 − 2 = 12. أما 2 فهي قيمة pOH وليست pH، والقيمتان 1 و13 تنتجان من كتابة التركيز 10⁻¹ خطأً.$q$),
    ('ac-030', 1, $q$معادلة التعادل: H₂SO₄ + 2NaOH → Na₂SO₄ + 2H₂O. مولات NaOH = 0.0250 × 0.20 = 0.0050 mol، ومولات الحمض نصفها = 0.0025 mol، فتركيز الحمض = 0.0025 ÷ 0.0200 = 0.125 M. أما 0.25 M فتنتج من إهمال أن كل جزيء حمض يعادل جزيئين من القاعدة.$q$),
    ('ac-031', 2, $q$الإشارة السالبة لـ ΔH تعني أن المحتوى الحراري للنواتج أقل منه للمتفاعلات، فيفقد النظام الفرق في صورة حرارة تنطلق إلى المحيط؛ وهذا هو التفاعل الطارد للحرارة.$q$),
    ('ac-032', 1, $q$من العلاقة q = m × c × ΔT تكون c = q ÷ (m × ΔT)، والتغير في درجة الحرارة ΔT = 35 − 25 = 10 °C؛ إذن c = 180 ÷ (20 × 10) = 0.90 J/(g·°C). أما 0.26 فتنتج من استعمال درجة الحرارة النهائية بدلًا من التغير فيها، و1.11 من قلب النسبة (m × ΔT) ÷ q، و9.00 من إهمال التغير في درجة الحرارة.$q$),
    ('ac-033', 0, $q$وفق قانون هس نُبقي المعادلة الأولى كما هي، ونعكس الثانية فتصبح ΔH لها +283 kJ، ثم نجمع المعادلتين فيُحذف CO₂ من الطرفين. إذن ΔH = −394 + 283 = −111 kJ.$q$),
    ('ac-034', 0, $q$ΔH = مجموع حرارات تكوين النواتج − مجموع حرارات تكوين المتفاعلات = [−394 + 2 × (−286)] − [−75 + 0] = −966 + 75 = −891 kJ. وحرارة تكوين O₂ صفر لأنه عنصر في حالته القياسية، أما −605 kJ فتنتج من إهمال المعامل 2 للماء.$q$),
    ('ac-035', 1, $q$يكون التفاعل تلقائيًا عندما تكون ΔG = ΔH − TΔS سالبة. عند الحد ΔG = 0 تكون T = ΔH ÷ ΔS = 40000 J ÷ 125 J/K = 320 K، ولأن ΔS موجبة فإن أي درجة أعلى من 320 K تجعل ΔG سالبة. أما 0.32 K فتنتج من إهمال تحويل kJ إلى J.$q$),
    ('ac-036', 2, $q$الصيغة العامة للألكينات غير الحلقية ذات الرابطة الثنائية الواحدة CₙH₂ₙ، وعندما n = 4 تكون الصيغة C₄H₈. أما C₄H₁₀ فصيغة ألكان (CₙH₂ₙ₊₂)، وC₄H₆ صيغة ألكاين (CₙH₂ₙ₋₂).$q$),
    ('ac-037', 3, $q$يحتوي المركب على مجموعة الهيدروكسيل (–OH) مرتبطة بذرة كربون مشبعة، وهي المجموعة الوظيفية للكحولات، والمركب هو الإيثانول. أما الأحماض الكربوكسيلية فمجموعتها –COOH، والإيثرات فيها ذرة أكسجين بين مجموعتي ألكيل.$q$),
    ('ac-038', 0, $q$أطول سلسلة كربونية متصلة تضم 4 ذرات (بيوتان)، وتُرقَّم من الطرف الأقرب إلى التفرع فتقع مجموعة الميثيل على الكربون رقم 2؛ لذا الاسم 2-ميثيل بيوتان. أما 3-ميثيل بيوتان فناتج عن الترقيم من الطرف الآخر، و2-ميثيل بنتان يضم 6 ذرات كربون بينما للمركب 5 ذرات فقط.$q$),
    ('ac-039', 1, $q$تنكسر رابطة باي في الرابطة الثنائية بين ذرتي الكربون، وترتبط ذرة بروم بكل منهما دون أن تنفصل أي ذرة عن الجزيء؛ فهو تفاعل إضافة يحوّل الألكين إلى مركب مشبع. أما الاستبدال فتحل فيه ذرة محل أخرى، والحذف عكس الإضافة.$q$),
    ('ac-040', 0, $q$في هذا الإستر يأتي الجزء CH₃CH₂COO– من الحمض، وفيه 3 ذرات كربون منها كربون مجموعة الكربونيل، فيُسمّى «بروبانوات»، وتأتي مجموعة الألكيل –CH₃ المرتبطة بذرة الأكسجين من الكحول، فتُسمّى «الميثيل»؛ لذا اسمه بروبانوات الميثيل. ويتكوّن بتفاعل أسترة منعكس بين حمض البروبانويك والميثانول: CH₃CH₂COOH + CH₃OH ⇌ CH₃CH₂COOCH₃ + H₂O، يعمل فيه حمض الكبريتيك المركز محفزًا ومادة نازعة للماء تزيح الاتزان نحو تكوين الإستر. أما إيثانوات الإيثيل وميثانوات البروبيل فمتشكلان له لهما الصيغة الجزيئية نفسها C₄H₈O₂، ويُختاران عند الخطأ في تحديد جزأي الإستر، وأما بيوتانوات الميثيل فتنتج من عدّ كربون مجموعة الميثيل ضمن سلسلة الحمض.$q$)
  ) as v (key, correct_index, explanation)
  join public.questions q on q.key = v.key
on conflict (question_id) do update set
  correct_index = excluded.correct_index,
  explanation   = excluded.explanation
where (k.correct_index, k.explanation) is distinct from (excluded.correct_index, excluded.explanation);

