  ('ab-023', 'achievement', 'biology', 'ecology', 2, $q$إذا كانت الطاقة المخزنة في منتجات نظام بيئي 50000 كيلوجول، فما مقدار الطاقة بالكيلوجول التي تصل تقريبًا إلى مستوى المستهلكات الثالثة وفق قاعدة 10%؟$q$, null, $q$["5","50","500","5000"]$q$::jsonb, 60, array[$q$هرم الطاقة$q$, $q$انتقال الطاقة$q$]::text[], (select s.id from public.question_sources s where s.slug = 'jazira-original'), null, null, 'ar', false, true),
  ('ab-024', 'achievement', 'biology', 'ecology', 2, $q$تعيش سمكة المهرج بين لوامس شقائق النعمان فتحتمي بها من المفترسات، وفي المقابل تنظّف السمكةُ الشقائقَ وتطرد عنها بعض الأسماك التي تتغذى عليها. ما نوع هذه العلاقة؟$q$, null, $q$["التعايش","التطفل","التقايض","التنافس"]$q$::jsonb, 60, array[$q$العلاقات التكافلية$q$, $q$التقايض$q$]::text[], (select s.id from public.question_sources s where s.slug = 'jazira-original'), null, null, 'ar', false, true),
  ('ab-025', 'achievement', 'biology', 'ecology', 3, $q$رُشَّ مبيد حشري لا يتحلل قرب بحيرة، فبلغ تركيزه 0.002 جزء من المليون في العوالق النباتية و20 جزءًا من المليون في الطيور آكلة الأسماك. إذا كان تركيزه يتضاعف بعدد المرات نفسه عند كل انتقال إلى المستوى الغذائي التالي في السلسلة: عوالق نباتية ← عوالق حيوانية ← أسماك صغيرة ← أسماك كبيرة ← طيور آكلة للأسماك، فكم مرة يتضاعف تركيزه عند كل انتقال؟$q$, null, $q$["10","2000","2500","10000"]$q$::jsonb, 75, array[$q$التضخم الحيوي$q$, $q$التلوث$q$]::text[], (select s.id from public.question_sources s where s.slug = 'jazira-original'), null, null, 'ar', false, true),
  ('ab-026', 'achievement', 'biology', 'classification-evolution', 1, $q$مِمَّ يتكوّن الاسم العلمي للمخلوق الحي في نظام التسمية الثنائية الذي وضعه لينيوس؟$q$, null, $q$["اسم المملكة يليه اسم الشعبة","اسم الفصيلة يليه اسم الرتبة","اسم النوع يليه اسم الطائفة","اسم الجنس يليه الاسم الواصف للنوع"]$q$::jsonb, 45, array[$q$التسمية الثنائية$q$, $q$التصنيف$q$]::text[], (select s.id from public.question_sources s where s.slug = 'jazira-original'), null, null, 'ar', false, true),
  ('ab-027', 'achievement', 'biology', 'classification-evolution', 1, $q$في التسلسل الهرمي للتصنيف، أيُّ المستويات الآتية أعمُّ ويضم أكبر عدد من الأنواع؟$q$, null, $q$["الطائفة","الرتبة","الفصيلة","الجنس"]$q$::jsonb, 45, array[$q$مستويات التصنيف$q$, $q$التصنيف$q$]::text[], (select s.id from public.question_sources s where s.slug = 'jazira-original'), null, null, 'ar', false, true),
  ('ab-028', 'achievement', 'biology', 'classification-evolution', 2, $q$تتشابه عظام الطرف الأمامي في الإنسان والحوت والخفاش في تركيبها الأساسي رغم اختلاف وظائفها. ماذا تُسمّى هذه التراكيب، وعلامَ تدل؟$q$, null, $q$["تراكيب متشابهة (Analogous) تدل على بيئة مشتركة","تراكيب متماثلة (Homologous) تدل على سلف مشترك","تراكيب أثرية (Vestigial) تدل على فقدان وظيفتها","تراكيب متشابهة (Analogous) تدل على سلف مشترك"]$q$::jsonb, 60, array[$q$أدلة التطور$q$, $q$التراكيب المتماثلة$q$]::text[], (select s.id from public.question_sources s where s.slug = 'jazira-original'), null, null, 'ar', false, true),
  ('ab-029', 'achievement', 'biology', 'classification-evolution', 2, $q$في جماعة حيوية من الخنافس لونُ بعض أفرادها أخضر ولونُ بعضها الآخر بنيّ، وكانت الطيور تلتقط الخنافس الخضراء بسهولة أكبر من فوق التربة البنية. ما النتيجة المتوقعة بعد أجيال عدة وفق الانتخاب الطبيعي؟$q$, null, $q$["تتحول الخنافس الخضراء إلى بنية لتتجنب الطيور","تتساوى نسبة اللونين لأن الطفرات تحدث عشوائيًّا","تزداد نسبة الخنافس الخضراء لقلة المنافسة بينها","تزداد نسبة الخنافس البنية لأنها تنجو وتتكاثر أكثر"]$q$::jsonb, 60, array[$q$الانتخاب الطبيعي$q$, $q$التكيف$q$]::text[], (select s.id from public.question_sources s where s.slug = 'jazira-original'), null, null, 'ar', false, true),
  ('ab-030', 'achievement', 'biology', 'classification-evolution', 3, $q$مخلوق حي وحيد الخلية لا يحتوي على نواة محاطة بغشاء، ويخلو جداره الخلوي من الببتيدوجلايكان، ويعيش في برك شديدة الملوحة. إلى أي مملكة يُصنَّف على الأرجح؟$q$, null, $q$["البكتيريا الحقيقية","البكتيريا القديمة","الطلائعيات","الفطريات"]$q$::jsonb, 75, array[$q$الممالك$q$, $q$البكتيريا القديمة$q$]::text[], (select s.id from public.question_sources s where s.slug = 'jazira-original'), null, null, 'ar', false, true),
  ('ab-031', 'achievement', 'biology', 'microbiology', 1, $q$مِمَّ تتكوّن جُدُر الخلايا في معظم الفطريات؟$q$, null, $q$["السليلوز","الببتيدوجلايكان","الكايتين","اللجنين"]$q$::jsonb, 45, array[$q$الفطريات$q$, $q$الجدار الخلوي$q$]::text[], (select s.id from public.question_sources s where s.slug = 'jazira-original'), null, null, 'ar', false, true),
  ('ab-032', 'achievement', 'biology', 'microbiology', 1, $q$يسبب مرضَ الملاريا طلائعيٌّ متطفل ينتقل إلى الإنسان عن طريق لدغة أنثى بعوضة الأنوفيليس. ما هذا الطلائعي؟$q$, null, $q$["البلازموديوم","الأميبا","البراميسيوم","اليوجلينا"]$q$::jsonb, 45, array[$q$الطلائعيات$q$, $q$الملاريا$q$]::text[], (select s.id from public.question_sources s where s.slug = 'jazira-original'), null, null, 'ar', false, true),
  ('ab-033', 'achievement', 'biology', 'microbiology', 2, $q$لماذا لا تفيد المضادات الحيوية في علاج نزلات البرد التي تسببها الفيروسات؟$q$, null, $q$["لأن الفيروسات أصغر حجمًا من أن تؤثر فيها","لأن الجسم يطرحها قبل أن تصل إلى الفيروس","لأنها تهاجم خلايا الجسم المصابة لا الفيروس","لأنها تستهدف تراكيب بكتيرية لا توجد في الفيروسات"]$q$::jsonb, 60, array[$q$المضادات الحيوية$q$, $q$الفيروسات$q$]::text[], (select s.id from public.question_sources s where s.slug = 'jazira-original'), null, null, 'ar', false, true),
  ('ab-034', 'achievement', 'biology', 'microbiology', 2, $q$دخلت المادة الوراثية لفيروس إلى خلية بكتيرية وأصبحت جزءًا من كروموسومها، وأخذت تتضاعف معه في كل انقسام دون أن تتحلل الخلية. أيُّ المصطلحات الآتية يصف ما يمر به الفيروس في هذه المرحلة؟$q$, null, $q$["الدورة الاندماجية","الدورة التحللية","النسخ العكسي","الاقتران البكتيري"]$q$::jsonb, 60, array[$q$الفيروسات$q$, $q$الدورة الاندماجية$q$]::text[], (select s.id from public.question_sources s where s.slug = 'jazira-original'), null, null, 'ar', false, true),
  ('ab-035', 'achievement', 'biology', 'microbiology', 2, $q$تنقسم خلية بكتيرية بالانشطار الثنائي كل 20 دقيقة في ظروف مثالية. إذا بدأت مزرعة بخلية واحدة، فكم يصبح عدد الخلايا في المزرعة بعد ساعتين؟$q$, null, $q$["6","12","32","64"]$q$::jsonb, 60, array[$q$البكتيريا$q$, $q$الانشطار الثنائي$q$]::text[], (select s.id from public.question_sources s where s.slug = 'jazira-original'), null, null, 'ar', false, true),
  ('ab-036', 'achievement', 'biology', 'biochemistry', 1, $q$ما الوحدات البنائية التي تتكوّن منها البروتينات؟$q$, null, $q$["السكريات الأحادية","النيوكليوتيدات","الأحماض الأمينية","الأحماض الدهنية"]$q$::jsonb, 45, array[$q$البروتينات$q$, $q$الجزيئات الحيوية$q$]::text[], (select s.id from public.question_sources s where s.slug = 'jazira-original'), null, null, 'ar', false, true),
  ('ab-037', 'achievement', 'biology', 'biochemistry', 2, $q$يعمل إنزيم في جسم الإنسان بأعلى كفاءة عند 37 °C. ماذا يحدث لنشاطه غالبًا عند رفع درجة الحرارة إلى 70 °C؟$q$, null, $q$["يتضاعف لأن الجزيئات تتصادم بسرعة أكبر","لا يتغير لأن الإنزيم لا يُستهلك في التفاعل","يزداد لأن الحرارة تخفض طاقة التنشيط","يتوقف تقريبًا لتغيّر شكل موقعه النشط"]$q$::jsonb, 60, array[$q$الإنزيمات$q$, $q$الموقع النشط$q$]::text[], (select s.id from public.question_sources s where s.slug = 'jazira-original'), null, null, 'ar', false, true),
  ('ab-038', 'achievement', 'biology', 'biochemistry', 2, $q$يتحلل جزيء جلوكوز واحد في مرحلة التحلل السكري داخل السيتوبلازم. ما عدد جزيئات حمض البيروفيك الناتجة، وما صافي ATP المتكوّن؟$q$, null, $q$["جزيئان من حمض البيروفيك وصافي 2 ATP","جزيء واحد من حمض البيروفيك وصافي 4 ATP","جزيئان من حمض البيروفيك وصافي 4 ATP","أربعة جزيئات من حمض البيروفيك وصافي 2 ATP"]$q$::jsonb, 60, array[$q$التنفس الخلوي$q$, $q$التحلل السكري$q$]::text[], (select s.id from public.question_sources s where s.slug = 'jazira-original'), null, null, 'ar', false, true),
  ('ab-039', 'achievement', 'biology', 'biochemistry', 2, $q$إذا كانت نسبة القاعدة النيتروجينية أدينين (A) في جزيء DNA مزدوج السلسلة 30%، فما نسبة القاعدة جوانين (G) فيه؟$q$, null, $q$["20%","30%","40%","70%"]$q$::jsonb, 60, array[$q$الأحماض النووية$q$, $q$تزاوج القواعد$q$]::text[], (select s.id from public.question_sources s where s.slug = 'jazira-original'), null, null, 'ar', false, true),
  ('ab-040', 'achievement', 'biology', 'biochemistry', 3, $q$زُوِّد نبات بماء يحتوي على نظير الأكسجين الثقيل (H₂¹⁸O) ثم عُرِّض للضوء ليقوم بالبناء الضوئي. في أي المواد الآتية يظهر النظير ¹⁸O أولًا؟$q$, null, $q$["في جزيئات الجلوكوز الناتجة","في غاز الأكسجين المنطلق","في ثاني أكسيد الكربون المنطلق","في جزيئات ATP المتكوّنة"]$q$::jsonb, 75, array[$q$البناء الضوئي$q$, $q$التفاعلات الضوئية$q$]::text[], (select s.id from public.question_sources s where s.slug = 'jazira-original'), null, null, 'ar', false, true)
