insert into public.question_keys as k (question_id, correct_index, explanation)
select q.id, v.correct_index, v.explanation
  from (values
    ('ab-001', 3, $q$تنص نظرية الخلية على أن جميع المخلوقات الحية تتكوّن من خلية واحدة أو أكثر، وأن الخلية هي الوحدة البنائية والوظيفية فيها؛ أما الذرة فوحدة بناء المادة عامةً وليست حية، والنسيج مجموعة من الخلايا، والنواة جزء داخل الخلية.$q$),
    ('ab-002', 0, $q$تجري في الميتوكندريا حلقة كربس وسلسلة نقل الإلكترونات من التنفس الخلوي الهوائي، وفيهما يُنتَج معظم ATP (عشرات الجزيئات لكل جزيء جلوكوز، مقابل صافي 2 فقط من التحلل السكري الذي يجري في السيتوبلازم)؛ أما البلاستيدات الخضراء فتحوّل الطاقة الضوئية إلى طاقة كيميائية مخزنة في السكر ولا تستخلص الطاقة من الغذاء، وجهاز جولجي يعدّل البروتينات ويغلّفها، والرايبوسومات تبني البروتينات.$q$),
    ('ab-003', 1, $q$وجود الجدار الخلوي يستبعد الخلية الحيوانية، والبلاستيدات الخضراء عُضيات محاطة بأغشية لا توجد في البكتيريا لأنها بدائية النوى، ولا في الفطريات لأنها لا تقوم بالبناء الضوئي؛ فاجتماع الجدار والبلاستيدات والفجوة المركزية الكبيرة من سمات الخلية النباتية.$q$),
    ('ab-004', 2, $q$المحلول مرتفع التركيز بالنسبة إلى الخلية، أي أن تركيز الماء خارجها أقل منه داخلها؛ فينتقل الماء بالخاصية الأسموزية من داخل الخلية إلى خارجها، فتفقد الخلية الماء وتنكمش.$q$),
    ('ab-005', 2, $q$يتضاعف DNA في الطور البيني فيتكوّن كل كروموسوم من كروماتيدين شقيقين، وفي الانقسام المنصف الأول تنفصل الكروموسومات المتماثلة، فتحتوي كل خلية ناتجة على n = 12 كروموسومًا، ويبقى كل كروموسوم مكوّنًا من كروماتيدين لأنهما لا ينفصلان إلا في الطور الانفصالي الثاني؛ فعدد الكروماتيدات في كل خلية خلال الطور الاستوائي الثاني = 12 × 2 = 24. أما 12 فهو عدد الكروموسومات لا الكروماتيدات، و48 عدد الكروماتيدات قبل اختزال العدد (في الطور الاستوائي الأول أو في الطور الاستوائي من الانقسام المتساوي)، و6 ناتج اختزال العدد مرتين وهو خطأ لأن الانقسام الثاني لا يختزل عدد الكروموسومات.$q$),
    ('ab-006', 1, $q$ينتج كلٌّ من الأبوين جاميتات تحمل T أو t بنسبة متساوية، فيعطي مربع بانيت الطرز الجينية TT : Tt : tt بنسبة 1 : 2 : 1؛ ولا تظهر صفة القِصَر المتنحية إلا في الطراز tt، أي 1/4 = 25%.$q$),
    ('ab-007', 0, $q$طراز الأب الجيني IᴬIᴮ فيعطي جاميتات تحمل Iᴬ أو Iᴮ، وطراز الأم ii فتعطي i فقط؛ فيكون الأبناء Iᴬi (فصيلة A) أو Iᴮi (فصيلة B)، ولا يمكن أن تظهر الفصيلة AB أو O.$q$),
    ('ab-008', 3, $q$في النسخ تُبنى سلسلة mRNA مكمّلة للقالب ومعاكسة له في الاتجاه، فيقابل الطرفُ ′5 من mRNA الطرفَ ′3 من القالب: يقابل A القاعدةَ U (لا توجد T في RNA)، ويقابل T القاعدةَ A، ويقابل C القاعدةَ G، ويقابل G القاعدةَ C؛ فيُنسخ TAC إلى AUG، وGGA إلى CCU، وTTC إلى AAG، ويكون mRNA مكتوبًا من الطرف ′5 إلى الطرف ′3 هو AUG CCU AAG. أما GAA UCC GUA فهو التتابع نفسه مكتوبًا في الاتجاه المعاكس (من الطرف ′3 إلى الطرف ′5)، وATG CCT AAG يحتوي على T التي لا توجد في RNA، وUAC GGA UUC هو القالب نفسه بعد وضع U مكان T وليس سلسلة مكمّلة له.$q$),
    ('ab-009', 1, $q$يُورَّث الجينان مستقلين، فاحتمال البذور الخضراء (yy) = 1/4، واحتمال البذور الملساء (RR أو Rr) = 3/4؛ فاحتمال اجتماع الصفتين = 1/4 × 3/4 = 3/16.$q$),
    ('ab-010', 2, $q$طراز الأم الجيني XᴮXᵇ وطراز الأب XᴮY؛ يرث الذكر كروموسوم Y من أبيه وأحد كروموسومَي X من أمه، فاحتمال أن يرث Xᵇ ويُصاب = 1/2 = 50%. أما 25% فهو احتمال أن يكون أي مولود ذكرًا مصابًا قبل معرفة جنسه.$q$),
    ('ab-011', 1, $q$يحتوي اللعاب على إنزيم الأميليز الذي يبدأ تحليل النشا إلى سكريات أبسط في الفم، ثم يُستكمل هضمه في الأمعاء الدقيقة؛ أما المعدة فيبدأ فيها هضم البروتينات بإنزيم الببسين، والأمعاء الغليظة يُمتص فيها الماء.$q$),
    ('ab-012', 0, $q$تحتوي خلايا الدم الحمراء على الهيموجلوبين، وهو بروتين يحتوي على الحديد يرتبط بالأكسجين في الرئتين ويطلقه في الأنسجة؛ أما خلايا الدم البيضاء فتدافع عن الجسم، والصفائح الدموية تسهم في تخثر الدم، والبلازما تنقل المواد الذائبة.$q$),
    ('ab-013', 3, $q$الكبيبة شبكة من الشعيرات الدموية داخل محفظة بومان، ويدفع ضغط الدم المرتفع فيها الماء والأملاح والجلوكوز واليوريا إلى المحفظة؛ ثم يُعاد امتصاص الماء والمواد المفيدة في الأنيبيب الكلوي والتواء هنلي، وتنقل القناة الجامعة البول المتكوّن.$q$),
    ('ab-014', 2, $q$معظم التشابكات العصبية في جسم الإنسان كيميائية، يفصل فيها شقٌّ ضيق بين نهاية المحور والخلية التالية، فعند وصول السيال تتحرر نواقل عصبية من حويصلات في نهاية المحور، فتنتشر عبر الشق وترتبط بمستقبلات على غشاء الخلية التالية فتنقل الإشارة كيميائيًّا؛ أما العبور الكهربائي المباشر فيقتصر على عدد قليل من التشابكات، والهرمونات تفرزها الغدد الصماء في الدم، وغمد الميلين يعزل المحور ويسرّع انتقال السيال على امتداده ولا يعبر التشابك.$q$),
    ('ab-015', 1, $q$ينتشر الأكسجين من الحويصلات الهوائية إلى الشعيرات الرئوية، ثم تنقله الأوردة الرئوية، وهي أوردة تحمل دمًا مؤكسجًا، إلى الأذين الأيسر فالبطين الأيسر الذي يضخه في الأبهر ومنه عبر الشرايين إلى عضلات الساق؛ أما الشريان الرئوي فيحمل الدم غير المؤكسج من البطين الأيمن إلى الرئتين.$q$),
    ('ab-016', 3, $q$يدخل ثاني أكسيد الكربون إلى الورقة عبر الثغور، ويُستخدم في حلقة كالفن مصدرًا لذرات الكربون في بناء السكريات؛ أما الأكسجين فمن نواتج البناء الضوئي ويخرج من الورقة، وبخار الماء يُفقد بالنتح.$q$),
    ('ab-017', 0, $q$ينقل نسيج الخشب الماء والأملاح الذائبة من الجذور إلى الساق والأوراق، بينما ينقل اللحاء السكريات الناتجة عن البناء الضوئي إلى أجزاء النبات؛ والبشرة نسيج يغطي النبات ويحميه، والكامبيوم نسيج مرستيمي يكوّن خلايا جديدة.$q$),
    ('ab-018', 2, $q$يُفقد معظم ماء النبات بالنتح عبر الثغور، وتتحكم الخلايا الحارسة في فتح الثغر وإغلاقه؛ فحين تفقد الماء ترتخي فيُغلَق الثغر ويقل النتح، وحين تمتلئ بالماء ينفتح الثغر.$q$),
    ('ab-019', 3, $q$في الانتحاء الضوئي تنتقل الأوكسينات إلى الجانب المظلل من الساق فتحفّز استطالة خلاياه أكثر من خلايا الجانب المضيء، فيطول الجانب المظلل أكثر وتنحني الساق نحو الضوء.$q$),
    ('ab-020', 2, $q$في الإخصاب المزدوج تندمج نواة ذكرية بالبويضة (n + n) فينتج زيجوت 2n، وتندمج النواة الذكرية الثانية بالنواتين القطبيتين (n + n + n) فينتج نسيج السويداء 3n؛ وبما أن n = 10 فإن 3n = 30 كروموسومًا.$q$),
    ('ab-021', 2, $q$العشب منتج يصنع غذاءه بالبناء الضوئي، والجراد مستهلك أول لأنه يتغذى على العشب، والضفدع يتغذى على الجراد فهو مستهلك ثانٍ، والثعبان مستهلك ثالث. ولاحظ أن الضفدع مستهلك ثانٍ مع أنه يشغل المستوى الغذائي الثالث، لأن المنتج يشغل المستوى الأول.$q$),
    ('ab-022', 1, $q$تحلل المحللات المخلفات وأجسام المخلوقات الميتة إلى مواد بسيطة تعود إلى التربة والهواء فيستفيد منها المنتجون، فتسهم في تدوير المواد في النظام البيئي؛ أما الطاقة فلا يُعاد تدويرها بل تُفقد على هيئة حرارة.$q$),
    ('ab-023', 1, $q$ينتقل نحو 10% فقط من الطاقة من كل مستوى غذائي إلى المستوى الذي يليه: المستهلكات الأولى 50000 × 0.1 = 5000، والثانية 5000 × 0.1 = 500، والثالثة 500 × 0.1 = 50 كيلوجول.$q$),
    ('ab-024', 2, $q$يستفيد الطرفان كلاهما: السمكة تحصل على الحماية، والشقائق تحصل على التنظيف والحماية من بعض آكليها، وهذه علاقة تقايض؛ أما في التعايش فيستفيد طرف ولا يتأثر الآخر، وفي التطفل يستفيد طرف ويتضرر الآخر، وفي التنافس يتضرر الطرفان.$q$),
    ('ab-025', 0, $q$المبيد غير القابل للتحلل يتراكم في الأنسجة ولا يُطرح، فيزداد تركيزه في المستويات الغذائية الأعلى (التضخم الحيوي). في السلسلة خمسة مستويات، أي أربعة انتقالات، وقد ازداد التركيز إجمالًا 20 ÷ 0.002 = 10000 مرة؛ وبما أن التضاعف يتكرر بالضرب لا بالجمع، فالمطلوب عدد إذا ضُرب في نفسه أربع مرات أعطى 10000، وهو 10 (10 × 10 × 10 × 10 = 10000). أما 10000 فهو التضاعف الكلي لا تضاعف الانتقال الواحد، و2500 و2000 ناتجا قسمة التضاعف الكلي على عدد الانتقالات أو عدد المستويات، وهي قسمة لا تصح لأن التضاعف المتكرر يُضرب ولا يُجمع.$q$),
    ('ab-026', 3, $q$يتكوّن الاسم العلمي من كلمتين باللاتينية: الأولى اسم الجنس وتبدأ بحرف كبير، والثانية تصف النوع وتبدأ بحرف صغير، مثل Homo sapiens للإنسان.$q$),
    ('ab-027', 0, $q$ترتيب المستويات من الأعم إلى الأخص: المملكة ثم الشعبة ثم الطائفة ثم الرتبة ثم الفصيلة ثم الجنس ثم النوع، وكل مستوى يضم المستويات التي تليه؛ فالطائفة أعم الخيارات وتضم أكبر عدد من الأنواع.$q$),
    ('ab-028', 1, $q$التراكيب المتماثلة (Homologous structures) أعضاء لها أصل تركيبي واحد وإن اختلفت وظائفها، وهي دليل على انحدار هذه المخلوقات من سلف مشترك؛ أما التراكيب المتشابهة (Analogous structures) فتؤدي الوظيفة نفسها لكنها مختلفة الأصل، كجناح الطائر وجناح الحشرة، فلا تدل على سلف مشترك، والتراكيب الأثرية (Vestigial structures) أعضاء فقدت وظيفتها أو ضعفت، أما عظام الطرف الأمامي هنا فتؤدي وظائف واضحة.$q$),
    ('ab-029', 3, $q$الخنافس البنية أكثر تلاؤمًا مع لون البيئة، فتنجو من الافتراس وتتكاثر أكثر وتورث صفة اللون البني لأبنائها، فتزداد نسبتها جيلًا بعد جيل؛ أما الفرد نفسه فلا يغيّر لونه استجابةً للحاجة، لأن الانتخاب الطبيعي يؤثر في الجماعة الحيوية عبر الأجيال، ولا تتساوى النسبتان لأن الانتخاب ليس عشوائيًّا وإن كانت الطفرات عشوائية، والخنافس الخضراء هي الأكثر تعرضًا للافتراس فتقل نسبتها.$q$),
    ('ab-030', 1, $q$غياب النواة المحاطة بغشاء يعني أنه بدائي النواة، فتُستبعد الطلائعيات والفطريات لأنها حقيقية النوى؛ وتحتوي جُدُر البكتيريا الحقيقية على الببتيدوجلايكان، فخلوّ الجدار منه مع العيش في بيئة قاسية شديدة الملوحة يدل على البكتيريا القديمة.$q$),
    ('ab-031', 2, $q$تتكوّن جُدُر خلايا معظم الفطريات من الكايتين، وهو كربوهيدرات معقد يحتوي على النيتروجين ويدخل أيضًا في تركيب الهيكل الخارجي للحشرات؛ أما السليلوز فيكوّن جُدُر الخلايا النباتية، والببتيدوجلايكان يوجد في جُدُر البكتيريا الحقيقية، واللجنين مادة تقوّي جُدُر خلايا الخشب في النباتات.$q$),
    ('ab-032', 0, $q$البلازموديوم طلائعي شبيه بالحيوان يعيش متطفلًا، تنقله أنثى بعوضة الأنوفيليس إلى دم الإنسان فيتكاثر في خلايا الكبد ثم في خلايا الدم الحمراء ويحطمها؛ أما الأميبا والبراميسيوم واليوجلينا فطلائعيات تعيش معظم أنواعها حرة في الماء.$q$),
    ('ab-033', 3, $q$تعطّل المضادات الحيوية تراكيب وعمليات خاصة بالخلايا البكتيرية، مثل بناء الجدار الخلوي أو عمل رايبوسوماتها، والفيروس لا يملك جدارًا خلويًّا ولا رايبوسومات خاصة به بل يستخدم أدوات الخلية العائلة، فلا يتأثر بها؛ فالسبب غياب الهدف لا صِغَر حجم الفيروس، والمضادات الحيوية لا تهاجم خلايا الجسم.$q$),
    ('ab-034', 0, $q$في الدورة الاندماجية يندمج DNA الفيروس في كروموسوم الخلية العائلة ويتضاعف معه في كل انقسام دون تكوين فيروسات جديدة؛ أما في الدورة التحللية فيوجّه الفيروس الخلية فورًا لإنتاج فيروسات جديدة ثم تتحلل الخلية، والنسخ العكسي بناء DNA من RNA في الفيروسات الارتجاعية، والاقتران نقل للمادة الوراثية من خلية بكتيرية إلى أخرى عبر اتصال مباشر.$q$),
    ('ab-035', 3, $q$عدد الانقسامات في ساعتين = 120 ÷ 20 = 6 انقسامات، ويتضاعف عدد الخلايا في كل انقسام، فعدد الخلايا = 2⁶ = 64 خلية.$q$),
    ('ab-036', 2, $q$ترتبط الأحماض الأمينية معًا بروابط ببتيدية لتكوّن سلاسل عديدة الببتيد تلتف لتكوّن البروتين؛ أما النيوكليوتيدات فتبني الأحماض النووية، والسكريات الأحادية تبني الكربوهيدرات، والأحماض الدهنية تدخل في تركيب الدهون.$q$),
    ('ab-037', 3, $q$الإنزيمات بروتينات، والحرارة المرتفعة تكسر الروابط التي تحفظ شكلها الثلاثي الأبعاد، فيتغير شكل الموقع النشط ولا تعود المادة المتفاعلة ترتبط به، فيتوقف نشاط الإنزيم تقريبًا؛ أما زيادة التصادمات فتسرّع التفاعل فقط حتى درجة الحرارة المثلى.$q$),
    ('ab-038', 0, $q$ينشطر الجلوكوز (6 ذرات كربون) في التحلل السكري إلى جزيئين من حمض البيروفيك (3 ذرات كربون لكل منهما)؛ ويُستهلك في بداية المرحلة 2 ATP ويُنتَج 4 ATP، فيكون الصافي 4 − 2 = 2 ATP.$q$),
    ('ab-039', 0, $q$يرتبط A دائمًا بـ T، ويرتبط C بـ G، فنسبة T = نسبة A = 30%، ومجموعهما 60%؛ فيتبقى 100% − 60% = 40% تتقاسمها G وC بالتساوي، فنسبة G = 20%.$q$),
    ('ab-040', 1, $q$في التفاعلات الضوئية يتحلل الماء لتعويض الإلكترونات التي فقدها الكلوروفيل، فتتحد ذرات أكسجينه لتنطلق على هيئة غاز O₂، لذلك يظهر ¹⁸O أولًا في الأكسجين المنطلق؛ أما ذرات الأكسجين في الجلوكوز فمصدرها ثاني أكسيد الكربون المثبَّت في حلقة كالفن.$q$)
  ) as v (key, correct_index, explanation)
  join public.questions q on q.key = v.key
on conflict (question_id) do update set
  correct_index = excluded.correct_index,
  explanation   = excluded.explanation
where (k.correct_index, k.explanation) is distinct from (excluded.correct_index, excluded.explanation);

commit;
